(window.TZ_CONTENT=window.TZ_CONTENT||{})["skr"]={"taaruf.001": "تحریک دا تعارف", "taaruf.002": "اے ہک غیر سیاسی، فرقہ پرستی توں پاک اصلاحی تحریک ہے جیڑھی امامِ ربانی مجدد الفِ ثانیؒ تے اپݨے مرشدینِ کاملین، شمس الکونین خواجہ محمد عبدالخالق نقشبندی، قادری، سہروردیؒ، شمس العارفین حضرت سائیں عبدالرزاق خالقی نقشبندیؒ تے امام الذاکرین سائیں محمد عظیم اللہ رزاقی نقشبندیؒ دے طریقے تے لوکاں کوں شریعت تے سنت دے پاسے سݙیندی ہے۔", "taaruf.003": "اتھاں نہ لالچ ہے، نہ شہرت تے کثرت دا شوق، صرف اللہ دی رضا تے دل تے نفس دی اصلاح ہے۔", "taaruf.004": "تحریک دے مقاصد", "taaruf.005": "تحریک اتباعِ سنت پاکستان ہک غیر سیاسی تے فرقہ پرستی توں پاک اسلامی تحریک ہے، جیندے وچ اُمتِ مسلمہ دا ہر فرد رکنیت گھن سڳدا ہے۔ ایں تحریک دے بنیادی مقاصد ایہ ہن:", "taaruf.006": "اڄ دے ایں فتنیاں بھرے دور وچ جݙاں بدعات تے خرافات اپݨے عروج تے ہن، اُمتِ مسلمہ وچ خوفِ خدا تے عشقِ مصطفیٰ ﷺ حاصل کرݨ کیتے بدعات تے خرافات توں بچݨ، تے شریعتِ مطہرہ تے سنتِ مصطفیٰ ﷺ کوں سکھݨ سکھاوݨ تے اُنہاں تے عمل کرݨ دا شوق پیدا کرݨ۔ ایں سلسلے وچ ودھ توں ودھ درس و تدریس دا اہتمام کرݨ دے نال نال ٹُردے پھردے شریعت تے سنت دی تبلیغ کرݨ۔", "taaruf.007": "شریعت، سنت تے قرآن دی تعلیم کوں ودھاوݨ کیتے ودھ توں ودھ دینی مدرسے قائم کرݨ۔", "taaruf.008": "خدمتِ خلق دا جذبہ پیدا کرݨ تے یتیم پروری کوں ودھاوݨ کیتے یتیم خانے قائم کرݨ۔", "taaruf.009": "خاص کر نوجوان نسل کوں بے حیائی تے برائی توں بچا تے پنج ویلے دی نماز باجماعت کیتے مسیت وچ گھن آوݨ۔", "taaruf.010": "روزمرہ دے علاوہ ویاہ شادی تے ٻئے خوشی غمی دے موقعیاں تے تھیوݨ آلیاں بدعات کوں مکاوݨ تے شریعت تے سنت کوں ودھاوݨ کیتے ودھ توں ودھ ذکرِ خدا تے ذکرِ مصطفیٰ ﷺ دیاں محفلاں کرواوݨ۔", "taaruf.011": "قرآن تے سنت دی روشنی وچ اولیائے کاملین دیاں اصل تعلیمات کوں ودھاوݨ، تے جعلی، شعبدہ باز، جدی پشتی پیراں دیاں من گھڑت تعلیمات دا خاتمہ کر تے اڄ دے زمانے وچ تصوف دے بگڑے ہوئے چہرے کوں تازگی ݙیوݨ۔", "taaruf.012": "کریم آقا ﷺ نال کامل محبت حاصل کرݨ کیتے درود و سلام تے ذکر تے نعت دیاں محفلاں کوں ودھاوݨ۔", "taaruf.013": "معاشرتی تے اخلاقی برائیاں کوں مکاوݨ تے چنگے سلوک تے اخلاقی تعلیمات کوں رواج ݙیوݨ۔", "taaruf.014": "زالاں وچ فیشن پرستی دی جاہ تے شرعی پردے تے اپݨے گھر آلیاں دی تابعداری دا رجحان پیدا کرݨ۔", "taaruf.015": "سارے عالمِ اسلام، خاص کر وطنِ عزیز پاکستان نال محبت تے وفاداری دا جذبہ پیدا کرݨ۔", "taaruf.016": "اوّل ویلے نماز پڑھݨ کوں ودھاوݨ۔ اڄ کل فجر تے ظہر دیاں نمازاں مسیتاں وچ ٻہوں دیر نال پڑھیاں ویندیاں ہن جیڑھا نماز توں غفلت کرݨ ہے، حالانکہ حنفی اوقات دے مطابق ویلا ٻہوں پہلے تھی ویندا ہے۔", "taaruf.017": "ناموسِ رسالت تے ختمِ نبوت دا تحفظ کرݨ تے یہود و ہنود تے قادیانیاں دیاں سازشاں کوں بے نقاب کرݨ۔", "taaruf.018": "اتباعِ رسول ﷺ", "taaruf.019": "قرآنِ کریم دی روشنی وچ", "taaruf.020": "سورۂ آلِ عمران وچ اللہ تعالیٰ فرمیندا ہے: <span class=\"kk-ar\" style=\"display:block\">قُلْ اِنْ كُنْتُمْ تُحِبُّوْنَ اللّٰهَ فَاتَّبِعُوْنِيْ يُحْبِبْكُمُ اللّٰهُ وَيَغْفِرْ لَكُمْ ذُنُوْبَكُمْ</span>(فرما ݙیوو! جے تساں اللہ نال محبت کریندے ہو تاں میݙی اتباع کرو، اللہ تہاݙے نال محبت کریسی تے تہاݙے سارے گناہ معاف فرما ݙیسی)۔ آپ ﷺ خدا تعالیٰ دے محبوب ہن، محب اوں بندے کوں وی اپݨا محبوب بݨا گھندا ہے جیندے وچ اپݨے محبوب دیاں عادتاں تے خصلتاں ݙیکھدا ہے۔ ایں سانگے آپ ﷺ دی تابعداری وچ کوشش کرݨ مقامِ محبوبیت تئیں پہنچاوݨ آلی تے گناہاں کوں مٹاوݨ آلی ہے۔ ہر دانا تے عقلمند تے واجب ہے جو ظاہر تے باطن وچ آپ ﷺ دی کمال تابعداری وچ کوشش کرے۔", "taaruf.021": "سورۃ الاحزاب وچ فرمایا: <span class=\"kk-ar\" style=\"display:block\">لَقَدْ كَانَ لَكُمْ فِيْ رَسُوْلِ اللّٰهِ اُسْوَةٌ حَسَنَةٌ لِّمَنْ كَانَ يَرْجُوا اللّٰهَ وَالْيَوْمَ الْاٰخِرَ وَذَكَرَ اللّٰهَ كَثِيْرًا</span>(بیشک تہاݙے کیتے رسول اللہ ﷺ بہترین نمونہ ہن، اوندے کیتے جیڑھا اللہ تے آخرت دے ݙینہ دی امید رکھدا ہے تے اللہ دا ذکر ٻہوں کریندا ہے)۔ ایں سانگے جیڑھا اللہ دے پاسے رجوع کرے تے آخرت دی تیاری کرݨ چاہوے تے ٻہوں ذکرِ الٰہی وی کرݨ آلا ہووے، اونکوں چاہیدا ہے جو زندگی دے ہر ہر پہلو وچ نبی کریم ﷺ دے روشن طریقے دی پیروی کرے۔", "taaruf.022": "سورۃ النساء وچ فرمایا: <span class=\"kk-ar\" style=\"display:block\">مَنْ يُّطِعِ الرَّسُوْلَ فَقَدْ اَطَاعَ اللّٰهَ</span>(جیں رسول ﷺ دی اطاعت کیتی، اوں حق تعالیٰ دی اطاعت کیتی)۔ پتہ لڳا جو اللہ تعالیٰ اپݨی اطاعت کوں اپݨے حبیب ﷺ دی اطاعت وچ لُکا تے رکھیا ہے۔ اطاعتِ رسول ای اطاعتِ الٰہی ہے تے ذکرِ رسول ﷺ عین ذکرِ خدا ہے۔ ہُݨ جیڑھا رسول اللہ ﷺ دی اطاعت کوں اللہ تعالیٰ دی اطاعت توں وکھری سمجھے او قرآن دا منکر ہے۔", "taaruf.023": "<b>اطاعتِ رسول ﷺ اللہ دے مقرب بندیاں دی رفاقت تے معیت دا ذریعہ:</b> سورۃ النساء وچ فرمانِ الٰہی ہے: <span class=\"kk-ar\" style=\"display:block\">وَمَنْ يُّطِعِ اللّٰهَ وَالرَّسُوْلَ فَاُولٰٓئِكَ مَعَ الَّذِيْنَ اَنْعَمَ اللّٰهُ عَلَيْهِمْ مِّنَ النَّبِيّٖنَ وَالصِّدِّيْقِيْنَ وَالشُّهَدَآءِ وَالصّٰلِحِيْنَ ۚ وَحَسُنَ اُولٰٓئِكَ رَفِيْقًا</span>(جیں اللہ تے اوندے رسول ﷺ دی اطاعت کیتی تاں اے لوک اُنہاں حضرات دے نال ہوسن جنہاں تے اللہ تعالیٰ انعام فرمایا، یعنی انبیاء، صدیقین، شہداء تے صالحین، تے اے حضرات ٻہوں چنگے ساتھی ہن)۔", "taaruf.024": "<b>رسول اللہ ﷺ دی اطاعت توں بغیر عمل ضائع تھی ویندے ہن:</b> سورۂ محمد وچ ارشادِ الٰہی ہے: <span class=\"kk-ar\" style=\"display:block\">يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْٓا اَطِيْعُوا اللّٰهَ وَاَطِيْعُوا الرَّسُوْلَ وَلَا تُبْطِلُوْٓا اَعْمَالَكُمْ</span>(ایمان آلو! اللہ دی اطاعت کرو تے رسول ﷺ دی اطاعت کرو تے اپݨے عملاں کوں ضائع نہ کرو)۔", "taaruf.025": "<b>اطاعتِ رسول ﷺ رحمتِ خداوندی دا ذریعہ:</b> سورۂ آلِ عمران وچ ہے: <span class=\"kk-ar\" style=\"display:block\">وَاَطِيْعُوا اللّٰهَ وَالرَّسُوْلَ لَعَلَّكُمْ تُرْحَمُوْنَ</span>(اللہ تے اوندے رسول ﷺ دی اطاعت کرو تاں جو تہاݙے تے رحم کیتا ونڄے)۔", "taaruf.026": "<b>اطاعتِ رسول ﷺ ݙوہاں جہاناں دی کامیابی دا سبب:</b> <span class=\"kk-ar\" style=\"display:block\">وَمَنْ يُّطِعِ اللّٰهَ وَرَسُوْلَهٗ فَقَدْ فَازَ فَوْزًا عَظِيْمًا</span>تے جیں اللہ تے اوندے رسول ﷺ دی اطاعت کیتی تاں اوں ٻہوں وݙی کامیابی حاصل کیتی۔ (سورۃ الاحزاب)", "taaruf.027": "سورۃ النور دی آیت ۵۱ وچ بامراد مومناں دی صفت بیان فرمائی: (مسلماناں دی ڳالھ تاں اے ہے جو جݙاں اُنہاں کوں کہیں مقدمے وچ اللہ تے اوندے رسول ﷺ دے پاسے سݙیا ویندا ہے تاں جو اُنہاں دے وچکار فیصلہ فرما ݙیوے تاں او آہدے ہن جو اساں سُݨیا تے من گھدا، تے ایہو لوک فلاح پاوݨ آلے ہن)۔ اڳلی آیت وچ فرمایا: <span class=\"kk-ar\" style=\"display:block\">وَمَنْ يُّطِعِ اللّٰهَ وَرَسُوْلَهٗ وَيَخْشَ اللّٰهَ وَيَتَّقْهِ فَاُولٰٓئِكَ هُمُ الْفَآئِزُوْنَ</span>(تے جیں اللہ تے اوندے رسول ﷺ دی اطاعت کیتی تے اللہ توں ڈریا تے تقویٰ اختیار کیتا، ایہو لوک کامیاب تھیوݨ آلے ہن)۔ ایں آیت دی وضاحت وچ حضرت عمرؓ فرمایا جو جیڑھا بندہ فرائض وچ اللہ تعالیٰ دی اطاعت تے سنتاں وچ رسول اللہ ﷺ دی پیروی کریندا ہے، تے گزریاں ہوئیاں غلطیاں پاروں اللہ تعالیٰ توں ڈردا ہے، تے آوݨ آلی زندگی وچ اللہ دی نافرمانی توں بچدا ہے، ایہو لوک کامیاب ہن، تے کامیاب او بندہ ہے جیکوں جہنم دی اڳ توں بچا تے جنت وچ داخل کر ݙتا ڳیا۔ (ضیاء القرآن)", "taaruf.028": "سورۃ الانفال وچ فرمایا: اے ایمان آلو! اللہ تے رسول ﷺ دے سݙݨ تے حاضر تھیوو جݙاں رسول تہاکوں اوں شئے کیتے سݙن جیڑھی تہاکوں زندگی ݙیسی۔ (۲۴)۔ حضور ﷺ دا سݙݨ ای اللہ تعالیٰ دا سݙݨ ہے۔", "taaruf.029": "سورۃ الحشر وچ فرمانِ الٰہی ہے: تے جو کجھ تہاکوں رسول ﷺ عطا فرماون او گھن گھنو تے جیں توں منع فرماون اوں توں رُک ونڄو تے اللہ توں ڈرو۔ (۷)۔ ایں آیتِ کریمہ توں پتہ لڳا جو آپ ﷺ دی اطاعت، یعنی احکامِ الٰہی تے عمل کرݨ تے منکرات توں رُکݨ واجب ہے، اللہ اونکوں سخت عذاب ݙیسی جیڑھا آپ ﷺ دی نافرمانی کرے۔", "taaruf.030": "احادیثِ مبارکہ دی روشنی وچ", "taaruf.031": "<span class=\"kk-ar\" style=\"display:block\">خَيْرُ الْهُدٰى هُدٰى مُحَمَّدٍ ﷺ</span>سب توں بہترین راہ حضرت محمد ﷺ دی راہ ہے۔ (بخاری)", "taaruf.032": "فرمانِ مصطفیٰ ﷺ ہے جو جیڑھا بندہ میݙی سنت توں منہ پھیرے یا ڄاݨ ٻجھ تے چھوڑ ݙیوے تاں او ساݙے وچوں کائنی تے نہ او قیامت دے ݙینہ شفاعت دا حقدار ہوسی۔ تے جیں میݙی سنت نال محبت کیتی اوں میݙے نال محبت کیتی، تے جیں میݙے نال محبت کیتی او جنت وچ میݙے نال ہوسی۔ (ترمذی)", "taaruf.033": "میݙی اُمت دا ہر بندہ جنت وچ داخل تھیسی مگر جیں میݙا انکار کیتا (او جنت وچ نہ ویسی)۔ پچھݨ تے فرمایا: جیں میݙی نافرمانی کیتی اوں میݙا انکار کیتا۔ ایں تے قرآن گواہ ہے: اوں ݙینہ ظالم بندہ اپݨے ہتھ چَب چَب تے آکھسی جو ہائے کاش! میں رسول اللہ ﷺ دی راہ اپݨائی ہوندی، ہائے افسوس! کاش میں فلاݨے کوں دوست نہ بݨایا ہوندا۔ (سورۃ الفرقان: ۲۷)", "taaruf.034": "حضور نبی کریم ﷺ دعا فرمائی جو میݙے نائباں تے اللہ تعالیٰ دی رحمت ہووے۔ کہیں عرض کیتی جو آپ ﷺ دے نائب کوݨ ہن؟ فرمایا: جیڑھے میݙی سنت نال محبت کریندے ہن تے اونکوں اللہ تعالیٰ دے بندیاں کوں سکھیندے ہن۔ (جامع بیان العلم و فضلہ)", "taaruf.035": "اپݨے وصال توں پہلے ارشاد فرمایا: تہاݙے وچ ݙو شئیں چھوڑ تے ویندا پیاں، جݙاں تئیں انہاں ݙوہاں تے مضبوطی نال قائم رہسو گمراہ نہ تھیسو، ہک کتاب اللہ تے ٻئی سنتِ رسول اللہ ﷺ۔ (بخاری، کتاب الاحکام)", "taaruf.036": "اکابرین دے اقوال دی روشنی وچ", "taaruf.037": "<b>ثانی اثنین سیدنا صدیقِ اکبر رضی اللہ عنہ:</b> خلیفۂ اول بݨݨ توں بعد اپݨے تاریخی خطبے وچ فرمایا جو جݙاں تئیں میں اللہ تعالیٰ تے اوندے رسول ﷺ دی اطاعت کراں، تساں میݙی اطاعت کرو تے جے میں اُنہاں دے خلاف کراں تاں میݙا ساتھ چھوڑ ݙیوو۔ آپؓ کوں اتباعِ رسول ﷺ دا کمال شوق ہا۔ ایندا اندازہ اوں ڳالھ مُہاڑ توں لڳ سڳدا ہے جیڑھی آپؓ دے وصالِ مبارک توں چند گھنٹے پہلے آپ رضی اللہ عنہ تے آپ دی پیاری دھی اُم المومنین سیدہ عائشہ صدیقہؓ دے وچکار تھئی۔ فرمایا: عائشہؓ! تساں رسولِ خدا ﷺ کوں کتنے کپڑیاں وچ دفن کیتا ہا؟ عرض کیتا جو ترائے چٹے کپڑیاں وچ جنہاں وچ نہ قمیص ہئی نہ عمامہ۔ فرمایا: رسول اللہ ﷺ کیڑھے ݙینہ وفات پائی؟ عرض کیتی: سوموار دے ݙینہ۔ فرمایا: اڄ کیڑھا ݙینہ ہے؟ عرض کیتا: سوموار۔ فرمایا: میکوں امید ہے جو میݙی وفات ایں ویلے تے رات دے وچکار تھیسی۔ ول اللہ دے فضل نال اینویں ای تھیا جو اللہ رب العزت وصال دے ویلے وی آپ رضی اللہ عنہ کوں اتباعِ رسول ﷺ دا شرف عطا فرمایا تے سوموار دے ݙینہ تریہٹھ سال دی عمرِ مبارک وچ آپ رضی اللہ عنہ دا وصال تھیا۔ فرمایا کریندے ہن جو جیں کم تے رسول اللہ ﷺ عمل فرمیندے ہن میں اونکوں کیتے بغیر نئیں چھوڑیندا، جے میں حضور ﷺ دے حال وچوں کہیں کم کوں چھوڑ ݙیواں تاں میکوں ڈر ہے جو سنتِ رسول ﷺ توں پھر ویساں۔", "taaruf.038": "<b>سلطان العارفین حضرت بایزید بسطامیؒ:</b> آپ کوں ہک بندے بارے پتہ لڳا جو او ہمیشہ توں قائم اللیل تے صائم النہار ہے۔ فرمایا: اوں اپݨے اندر مجاہدے نال فرشتیاں آلیاں صفتاں پیدا کر گھدیاں ہن مگر اے کوئی مقام کائنی تے نہ ای اے ولایت ہے، بلکہ کمالِ ولایت اے ہے جو اپݨے اندر صفاتِ محمدی ﷺ پیدا کرے، یعنی اپݨی زندگی دے سارے ویلے، اپݨا قیام تے صیام تے ڳالھ مُہاڑ تے کھاݨا سنتِ مصطفیٰ ﷺ دے مطابق ڈھال گھنے۔ شریعت دی راہ پلِ صراط توں وی ودھ باریک تے خطرناک ہے، ایں سانگے کہیں وی حالت وچ شریعت دیاں حداں توں باہر قدم نئیں رکھݨا چاہیدا۔", "taaruf.039": "<b>سید الطائفہ شیخ جنید بغدادیؒ:</b> فرمیندے ہن جو اتباعِ شریعت تاں صرف اوہو کر سڳدا ہے جیندے سڄے ہتھ وچ قرآن پاک ہووے تے کھٻے ہتھ وچ سنتِ مصطفیٰ ﷺ۔ انہاں ݙوہاں ݙیویاں دی روشنی وچ راہ طے کرے تاں جو نہ شبہے دے کھڈیاں وچ ڈھوے نہ بدعت دے ہنیریاں وچ پھسے۔", "taaruf.040": "<b>غوثِ زماں شیخ ابوالقاسم گرگانیؒ:</b> فرمیندے ہن جو پاݨی دی سطح تے ٹُرݨ، ہوا وچ اُݙرݨ تے غیب دیاں ڳالھیں معلوم کرݨ تے بیان کرݨ، انہاں وچوں کہیں کوں وی کرامت نئیں آکھ سڳدے کیوں جو اے سب کجھ تاں شیطان دی مدد نال وی ممکن تھی سڳدا ہے، بلکہ کتنے ای کاہن ہن جیڑھے غیب دیاں ڳالھیں بیان کر ݙیندے ہن۔ بلکہ سب توں وݙی کرامت اے ہے جو بندہ سراپا امرِ الٰہی بݨ ونڄے تے تن من دھن نال شریعت دا تابع تھی ونڄے تے اوندے کہیں کم یا حرکت وچ احکامِ شریعت دی خلاف ورزی دا شائبہ تئیں نظر نہ آوے۔ جے حالت اینویں ہووے تاں او قابلِ اعتبار ہے۔ متابعتِ شریعت وچ جے توں شینہ تے سواری نہ کر سڳیں تاں کوئی حرج کائنی کیوں جو غصے تے غضب دے اوں کتے، یعنی نفس کوں جیڑھا تیݙے سینے وچ موجود ہے، مغلوب کر گھنݨ ٻہوں سارے شینہاں تے سواری کرݨ توں کئی درجے افضل ہے۔ نفس دے مکر تے فریب توں آگاہی حاصل کر گھنݨ سب توں وݙی غیب دانی ہے۔ حس تے خیال دے دائرے توں باہر تھی ونڄݨ پاݨی تے ٹُرݨ تے ہوا وچ اُݙرݨ توں کجھ گھٹ تاں کائنی۔ دنیا دے لالچ تے دنیاوی مشغلیاں توں بے نیاز تھی تے اڳوں نکل ونڄݨ تے ہک مشتبہ یعنی شک آلے درہم کوں ٹھکرا ݙیوݨ ٻہوں وݙے وݙے میداناں کوں، جنگلاں کوں ٹپ ونڄݨ تے ہک اوکھی گھاٹی کوں پار کر گھنݨ توں گھٹ تاں کائنی، جو حق تعالیٰ انہاں رکاوٹاں کوں اپݨے کلامِ پاک وچ گھاٹیاں دا ناں ݙتا ہے۔", "taaruf.041": "<b>حضرت داتا گنج بخش ہجویریؒ:</b> روحانی ترقی کیتے اتباعِ شریعت کوں لازمی قرار ݙیندے ہوئے فرمیندے ہن جو شریعت وچ پہلا رکن کتاب ہے۔ جیویں خدا تعالیٰ فرمیندا ہے: قرآن پاک وچ آیاتِ محکمات ہن جو او اصل کتاب ہن۔ (سورۂ آلِ عمران: ۷)۔ ݙوجھا رکن سنتِ رسول ﷺ ہے جیندا ماخذ احادیث ہن۔ جیویں قرآن پاک وچ ہے: تے جو رسول اللہ ﷺ فرمایا ہے اوں تے عمل کرو تے جیں ڳالھ توں منع فرمایا ہے اوں توں بچو۔ (سورۃ الحشر)۔ تریجھا رکن اجماعِ اُمت ہے جو رسول اللہ ﷺ فرمایا: میݙی اُمت گمراہی تے جمع نئیں تھیندی، ہمیشہ سوادِ اعظم کوں اختیار کرو۔ ایں نال تقلید دا جائز ہووݨ وی واضح تھی ڳیا۔ کوئی صوفی شریعت تے حقیقت وچ فرق نئیں کر سڳدا۔ صوفیانہ تعلیمات پوری طرح احکامِ شریعت دے تابع ہن۔ ایں سانگے طریقت اصل وچ شریعت کوں ای اپݨی زندگی دیاں ڈونگھائیاں وچ پاوݨ دا ناں ہے۔", "taaruf.042": "<b>غوث الاعظم محی الدین شیخ عبدالقادر جیلانیؒ:</b> فرمایا جو ہنیرے وچ ݙیوا گھن تے داخل تھی تے او ݙیوا کتاب اللہ تے نبی کریم ﷺ دی سنتِ مبارکہ ہے۔ کتاب تے سنت دے احکام توں ہرگز باہر نہ نکل۔ جے تیݙے دل وچ کوئی خطرہ آوے جیویں زنا، سود تے فاسق فاجر لوکاں نال میل جول وغیرہ، یا الہام پیدا تھیوے تاں اونکوں کتاب تے سنت دی روشنی وچ ݙیکھ، جے توں کتاب تے سنت وچ اوندی حرمت پاویں تاں اونکوں قبول نہ کر تے اوں توں وکھرا تھی ونڄ تے اے یقین کر گھن جو او شیطان مردود دے پاسوں ہے۔ بندہ شرع دیاں حداں دی حفاظت پاروں اوں غلام وانگوں تھی ویندا ہے جیکوں مالک سارے کم سونپ ݙیندا ہے۔ (فتوح الغیب)", "taaruf.043": "<b>شیخ الشیوخ شیخ شہاب الدین عمر سہروردیؒ:</b> سلسلہ سہروردیہ دے بانی، حضرت بہاؤالدین زکریاؒ دے مرشد، کتاب عوارف المعارف وچ فرمیندے ہن جو رسولِ اکرم ﷺ فرمایا: اوں ذات دی قسم جیندے قبضے وچ میݙی جان ہے! اللہ تعالیٰ کوں اوہو لوک محبوب ہن جیڑھے اوندے بندیاں وچ محبتِ الٰہی دا جذبہ جڳیندے ہن تے اُنہاں کوں اللہ دا محبوب بݨاوݨ دی کوشش کریندے ہن، بلکہ زمین تے ہر بندے دی خیر خواہی کیتے سرگرمِ عمل رہندے ہن۔ ایں حدیث وچ مشائخِ کرام دیاں صفتاں بیان کیتیاں ڳیاں ہن۔ شیخ دعوت الی اللہ وچ پیغمبراں دی نیابت کریندے ہوئے اپݨے مرید وچ اللہ دی محبت اینویں پیدا کریندا ہے جو اونکوں رسولِ اکرم ﷺ دی اتباع تے پیروی دی راہ تے لا تے تزکیۂ نفس دی راہ تے ٹوریندا ہے۔ ایں سانگے جیڑھا صحیح طریقے نال رسولِ اکرم ﷺ دی اتباع کریندا ہے تاں اللہ وی اوندے نال محبت کرݨ لڳ پوندا ہے۔", "taaruf.044": "<b>امام الطریقت خواجۂ خواجگان سید محمد بہاؤالدین نقشبندؒ:</b> ساݙے طریقے دی بنیاد احادیث تے آثار دی متابعت تے ہے تے ساݙا مقصد اے ہے جو ساݙا سلوک سنتِ رسول ﷺ دی اتباع تے ہووے تے حق دی باطل توں تمیز تھیندی ہووے۔ خاصانِ خدا او ہن جیڑھے شریعتِ مطہرہ دی پیروی کرن تے اہلِ سنت و الجماعت دے مذہب تے اپݨی زندگی پوری کرن۔ جے ریاضت وچ کمر ٹیڈھی تھی تے تہاݙا بدن کمان وانگوں تھی ونڄے تے ریاضت وچ وی کامیاب ہووے، مگر جݙاں تئیں اپݨا لقمہ تے لباس پاک نہ کرے تے شریعتِ رسول ﷺ دی پیروی نہ کرے، منزلِ مقصود تئیں نہ پہنچسی۔ ایں سانگے سارے کماں دا دارومدار ایں تے ای ہے۔ (انیس الطالبین)", "taaruf.045": "<b>امامِ ربانی محبوبِ سبحانی حضرت مجدد الف ثانیؒ:</b> فرمیندے ہن جو شریعت دے ترائے جز علم، عمل تے اخلاص ہن۔ جݙاں تئیں اے ترائے جز ثابت نہ ہوون شریعت حاصل نئیں تھیندی۔ تے جݙاں شریعت حاصل تھی ڳئی تاں جیویں حق تعالیٰ دی رضا حاصل تھی ڳئی، جیویں ارشادِ الٰہی ہے: (تے اللہ تعالیٰ دی رضا سب توں ودھ تے ہے)۔ ایں سانگے ایہو جیہا کوئی مطلب باقی کائنی جیکوں حاصل کرݨ کیتے شریعت دے سوا کہیں ٻئی شئے دی لوڑ پووے۔ طریقت تے حقیقت جنہاں نال صوفیا ممتاز ہن، اے شریعت دے تریجھے جز اخلاص کوں کامل کرݨ وچ شریعت دے خادم ہن۔ ایں سانگے انہاں ݙوہاں دی تکمیل دا مقصد شریعت دی تکمیل ہے، نہ جو شریعت دے سوا کوئی ٻیا کم۔ زبان نال کوڑ نہ ٻولݨ شریعت ہے تے دل وچوں کوڑ دا خطرہ دور کرݨ، یعنی سچائی دی عادت بغیر تکلیف تے بناوٹ دے حاصل تھی ونڄݨ، حقیقت یعنی تصوف ہے۔ ایں سانگے تصوف شریعت کوں کامل کرݨ آلا ہے نہ جو اوندا مخالف۔ او علوم تے معارف جیڑھے صوفیاء کوں ایں راہ وچ حاصل تھیندے ہن او اصلی مقصد کائنی بلکہ وہم تے خیالات ہن جنہاں نال طریقت دے ٻالاں دی تربیت کیتی ویندی ہے۔ انہاں سبھ توں لنگھ تے مقامِ رضا تئیں پہنچݨا چاہیدا ہے کیوں جو اے جذبہ تے سلوک دا سب توں اُچا مقام ہے۔ بے سمجھ لوک انہاں تجلیات تے مشاہدات کوں اصلی مقصد سمجھ تے شریعت دے کمالات توں محروم رہ ویندے ہن۔ ہاں مقامِ اخلاص تے مرتبۂ رضا تئیں پہنچݨ انہاں احوال کوں طے کرݨ تے علوم تے معارف دے حصول تے منحصر ہے۔ ایں سانگے اے احوال تے معارف اصل مطلب دے حصول کیتے اسباب تے وسیلہ ہن۔ شریعت احوال دے تابع کائنی بلکہ باطنی احوال شریعت دے تابع ہن، کیوں جو شریعت قطعی ہے، وحی نال ثابت ہے تے احوال گمانی ہن جیڑھے کشف تے الہام نال ثابت تھیندے ہن۔ ایں سانگے جیں گروہ کوں حق تعالیٰ آپ ﷺ دی اتباع پاروں نہایت النہایہ تئیں پہنچایا ہے او علم تے عمل وچ وال برابر وی شریعت دا مخالف نئیں تھیندا۔ تے علومِ لدنی جیڑھے اُنہاں تے وارد تھیندے ہن او شریعت دے موافق ہن بلکہ علومِ شرعیہ دی تفصیل ہن۔ ہر او کشف جیڑھا ظاہرِ شریعت دے خلاف ہووے قبول دے قابل کائنی کیوں جو او آپ ﷺ دی راہ توں ہٹ تے ہے۔ سورۂ یٰسین وچ فرمانِ الٰہی ہے: (بیشک آپ ﷺ رسولاں وچوں ہو تے صراطِ مستقیم تے ہو)۔ حیرانی ہے جو کجھ ناقص لوک اپݨے خیالی کشف کوں معتبر سمجھدے ہن تے روشن شریعت دی مخالفت تے انکار وچ کوشش کریندے ہن، حالانکہ حضرت موسیٰ علیہ السلام وی اپݨی کلیمی تے خاص قرب دے باوجود جے دنیا وچ ہوندے تاں او وی ایں شریعتِ مطہرہ دی پیروی کریندے۔", "taaruf.046": "سورۃ البقرہ وچ ہے: جیڑھے ایمان آلے ہن اُنہاں دی محبت اللہ کیتے ٻہوں شدید ہے۔ (۱۶۵)۔ ایں سانگے شرعی احکام بجا گھن آوݨ دی توفیق محبتِ الٰہی دا نتیجہ ہے تے باطنی جمعیت دا حاصل تھیوݨ ایں محبت دا پھل ہے۔ جے سارے جہان جتنیاں ظلمتاں تے کدورتاں باطن وچ پا ݙیون تے ایں محبت کوں قائم رکھن تاں کوئی غم نئیں کرݨا چاہیدا، تے جے سارے پہاڑاں برابر انوار تے کیفیات باطن وچ ودھا ݙیون لیکن ایں محبت وچ وال برابر کمی کر ݙیون تاں ایکوں خرابی دے سوا کجھ نہ سمجھݨا چاہیدا۔ سچے تے کوڑے دے وچکار فرق شریعت تے استقامت یا عدمِ استقامت نال پتہ لڳدا ہے۔ جیڑھا بندہ سچا ہے او سکر تے مستی تے بے خودی دے باوجود وال برابر وی شرع دے خلاف نئیں کریندا۔ مولانا رومؒ استغراق وچ رہندے ہن مگر نماز دے ویلے ہوش وچ آ ویندے ہن۔", "taaruf.047": "رسول اللہ ﷺ فرمایا: تہاݙے وچوں کوئی مومن نہ تھیسی جݙاں تئیں اوندی خواہش اوں امر دے تابع نہ تھی ونڄے جیڑھا میں گھن آیا ہاں۔ ایں سانگے شرعی تکلیفاں وچ حکمت ایہا ہے جو نفسِ امارہ خراب تے عاجز تھیوے۔ جتنا شریعت دے موافق عمل کیتا ونڄے اتنیاں ای نفسانی خواہشاں گھٹ تھی ویندیاں ہن۔ ایہا وجہ ہے جو احکامِ شرعی وچوں ہک حکم کوں بجا گھن آوݨ نفسانی خواہشاں کوں دور کرݨ وچ اُنہاں ہزار سالہ ریاضتاں تے مجاہدیاں توں جیڑھے اپݨے کولوں کیتے ونڄن، کئی درجے بہتر ہے، بلکہ ایہو جیہیاں ریاضتاں تے مجاہدے جیڑھے شرع دے موافق نہ ہوون او نفسانی خواہشاں کوں مدد تے طاقت ݙیوݨ آلے ہن۔ برہمناں تے جوگیاں کوں محنت مجاہدیاں نال نفس دی تقویت تے تربیت دے سوا کجھ فائدہ نہ تھیا۔ مثال دے طور تے نمازِ فجر دیاں ݙو رکعتاں جماعت نال ادا کرݨ، جیڑھا سنتاں وچوں ہک سنت ہے، ساری رات قیام کر تے نمازِ فجر بغیر جماعت دے ادا کرݨ توں کئی درجے بہتر ہے، تے شریعت دے حکم نال عید الفطر دے ݙینہ کھاݨا اپݨی مرضی نال کئی سال روزے رکھݨ توں بہتر ہے، تے نفس کوں خراب کرݨ کیتے زکوٰۃ دے طور تے ہک روپیہ خرچ کرݨ اپݨی مرضی نال ہزار روپے خرچ کرݨ توں بہتر ہے۔ مطلب اے جو جݙاں تئیں نفس صاف تھی تے سرداری دی پلیدی توں پاک نہ تھی ونڄے تݙاں تئیں نجات اوکھی ہے تے ہمیشہ دی موت تئیں پہنچݨ دا خطرہ ہے۔", "taaruf.048": "پسندیدہ متابعت دا ہک ذرہ ساریاں دنیاوی لذتاں تے آخرت دیاں نعمتاں توں کئی درجے بہتر ہے۔ بزرگی سنت دی تابعداری تے، تے زیادتی شریعت دی بجا آوری تے منحصر ہے۔ جو کجھ شریعت دے مخالف ہے مردود ہے۔ جیں حقیقت کوں شریعت رد کر ݙتا او زندیقہ ہے۔ شریعت کوں اپݨی جاہ تے قائم رکھ تے حقیقت کوں طلب کرݨ بہادراں دا کم ہے۔ حضور ﷺ دے دین دی حقیقت دی تصدیق کرݨ توں بعد تھوڑا جیہا عمل وی بجا گھن آوݨ ٻہوں عمل دے برابر ہے۔ اصحابِ کہف اتنا وݙا درجہ صرف ہک ای نیکی پاروں حاصل کیتا تے او نورِ ایمانی دے نال خدا تعالیٰ دے دشمناں دے غلبے دے ویلے ہجرت کر ونڄݨ ہا، کیوں جو دشمناں دے غلبے دے ویلے جے تھوڑی جیہی وی کوشش کرن تاں اتنی نمایاں تے قابلِ اعتبار ہوندی ہے جو امن دے ݙینہاں وچ ایں توں کئی گُݨا عمل وی اعتبار وچ نئیں آ سڳدا۔ جے ظاہری ہجرت نصیب نہ تھی سڳے تاں باطنی ہجرت کوں سامݨے رکھدے ہوئے مخلوق دے وچکار رہندے ہوئے اُنہاں توں وکھرا رہݨا چاہیدا ہے۔ محشر دے ݙینہ شریعت بارے پچھسن نہ جو تصوف بارے۔ جنت وچ داخل تھیوݨ تے دوزخ توں بچݨ شریعت دے احکام بجا گھن آوݨ تے منحصر ہے۔ انبیاء کرام دی پیدائش دا مقصد احکامِ شریعت کوں لوکاں تئیں پہنچاوݨ ای ہے۔ ایں سانگے سب توں وݙی بھاری نیکی ایہا ہے جو شرع کوں رواج ݙیوݨ تے ایندے احکام وچوں کہیں حکم کوں زندہ کرݨ وچ کوشش کیتی ونڄے، خاص کر ایہو جیہے زمانے وچ جݙاں اسلام دے نشان بالکل مٹ ڳئے ہوون۔ تے جیں بندے نال ٻہوں سارے لوکاں دی نجات جُڑی ہوئی ہووے او اوں بندے توں بہتر ہے جیڑھا صرف اپݨی نجات دے خیال وچ ہے۔", "taaruf.049": "ارشادِ الٰہی ہے: (بیشک اے میݙی سدھی راہ ہے، تساں ایں تے ٹُرو تے ٻیاں راہواں تے نہ ٹُرو)۔ رسول اللہ ﷺ فرمایا: میکوں میݙے رب ادب سکھایا تے میݙی تعلیم تے تادیب چنگی طرح کیتی۔ ایں سانگے جے طریقت تے حقیقت دی راہ تے ٹُرݨ آلیاں کولوں راہ دے دوران ایہو جیہے کم تھی ونڄن جیڑھے ظاہری طور تے شریعت دے خلاف ہوون تاں او غلبۂ حال یعنی مستی تے مبنی ہن، تے ایں مقام توں لنگھ تے ہوش وچ آوݨ تے او مخالفت مُک ویندی ہے۔ محمدی المشرب بزرگ شرع تے سنت دی دولت نال مشرف ہن تے ولایتِ خاصۂ محمدی ﷺ اُنہاں دا حصہ ہے۔ فنائے اتم تے بقائے اکمل انہاں دی ای شان ہے۔ تے ایندا مخالف بھانویں اولیاء وچوں ہووے تے اونکوں کشف تھیندا ہووے، اوندا ایں ولایت وچ حصہ کائنی تے او پچھلے پیغمبراں وچوں کہیں پیغمبر دے قدم تے ہے تے اوندے علوم اوں نبی دی شریعت دے موافق ہن۔ شریعتِ محمدی ﷺ ٻیاں شریعتاں دا خلاصہ ہے۔ شریعت تے سنت دی اتباع توں بغیر ایں منزل تئیں پہنچݨ محال ہے۔ ایں سانگے اوں بندے کیتے مبارکباد ہے جیکوں ایں بھاری نعمت دا شرف حاصل تھیا تے افسوس ہے اوں بندے تے جیڑھا اعلیٰ نعمت توں محروم رہیا۔", "taaruf.050": "آپ ﷺ دی ظاہری میراث دا شکر اے ہے جو باطنی میراث نال آراستہ تھیا ونڄے، تے باطنی میراث نال آراستہ تھیوݨ آپ ﷺ دی کامل پیروی توں بغیر ناممکن ہے۔ تے آپ ﷺ نال کمال محبت دی نشانی اے ہے جو حضور ﷺ دے دشمناں نال بغض رکھوں تے شریعت دے مخالفاں نال عداوت دا اظہار کروں۔ محبت وچ چاپلوسی جائز کائنی کیوں جو محب اپݨے محبوب دا دیوانہ ہوندا ہے تے ݙو مخالف محبتاں کٹھیاں نئیں تھی سڳدیاں۔ ایں سانگے لازم ہے جو اپݨی ساری ہمت احکامِ شریعہ دی بجا آوری، اہلِ شریعت علماء تے اولیاء دی تعظیم بجا گھن آوݨ تے بدعتیاں کوں خوار رکھݨ وچ لاؤں۔ جیں کہیں بدعتی دی تعظیم کیتی، جیویں اسلام ڈھاوݨ وچ اوندی مدد کیتی۔ حق تعالیٰ اپݨے نبی ﷺ دے طفیل ساݙے ظاہر تے باطن کوں سنتِ رسول ﷺ دی متابعت نال آراستہ تے پیراستہ کرے۔ (مکتوباتِ امامِ ربانی مجدد الف ثانیؒ)", "taaruf.051": "ساݙیاں گزارشاں", "taaruf.052": "حب الوطنی دا جذبہ", "taaruf.053": "وطن نال محبت ہک فطری تے چنگی ڳالھ ہے۔", "taaruf.054": "ایں سانگے اساکوں چاہیدا ہے جو دینِ اسلام دی سربلندی تے اپݨے وطنِ عزیز پاکستان دی مضبوطی کیتے رات ݙینہ کوشش وچ رہوں۔ نال اپݨے ٻالاں دے دلاں وچ خوفِ خدا تے عشقِ مصطفیٰ ﷺ دے نال نال حب الوطنی دا جذبہ وی پیدا کروں۔ ایندا بہترین طریقہ اے ہے جو جشنِ آزادی دے موقعے تے وی اللہ تعالیٰ تے نبی کریم ﷺ دے ذکر دے نال اپݨے اسلاف دیاں سیرتاں وی بیان کیتیاں ونڄن۔ نال جیڑھا بندہ جیں محکمے وچ اپݨے فرائض سرانجام ݙیندا ہووے او سچائی تے دیانتداری کوں اپݨا شعار بݨاوے، اتھوں تئیں جو گھر وچ رہݨ آلیاں زالاں تے مرد وی اپݨیاں ذمہ داریاں چنگے طریقے نال سرانجام ݙیون۔ اپݨے معاشرے کوں بہتر بݨاوݨ کیتے اپݨے ہمسایاں تے نیڑے دے مسکیناں تے فقیراں دا خیال رکھو، آپت وچ پیار محبت، اتفاق، اتحاد تے چنگے سلوک نال زندگی گزارو۔ ہک چنگا مسلمان ای چنگا انسان تے ہک چنگا پاکستانی تھی سڳدا ہے۔", "taaruf.055": "بے پردگی تے موبائل فوناں دا منفی استعمال تے ایندا تدارک", "taaruf.056": "سورۃ النور وچ فرمانِ الٰہی ہے: تے آپ (ﷺ) مسلمان عورتاں کوں فرما ݙیوو جو او اپݨیاں نظراں نیویاں رکھن تے اپݨی عفت دی حفاظت کرن تے اپݨا بݨاؤ سنگھار ظاہر نہ کرن۔ (۳۱)۔ تے فرمایا: اپݨے گھراں وچ سکون نال ٹکیاں رہو تے پراݨی جاہلیت دی بے پردگی وانگوں نہ رہو۔ (سورۃ الاحزاب)۔ تے فرمایا: خیمیاں دے اندر پردہ نشین حوراں ہن۔ (سورۃ الرحمٰن: ۷۲)۔ جنت وچ حوراں وی پردہ کریسن جتھاں برائی دا کوئی خدشہ وی نہ ہوسی۔ اصل وچ پردہ تاں عورت دی حیا تے حُسن ہے۔", "taaruf.057": "اڄ ایں فتنیاں بھرے دور وچ جݙاں بے پردگی تے بے حیائی عروج تے ہے، اساکوں اپݨیاں پاکیزہ دھیاں دی عفت دے تحفظ کیتے رل تے بے پردگی دی ایں بُری رسم کوں مکاوݨا پوسی، تے اپݨیاں نوہاں دھیاں کوں شرعی پردہ کرݨ دی ترغیب ݙیوݨی پوسی۔ اڄ دیاں روشن خیال زالاں آہدیاں ہن جو پردہ تاں نظر دا ہوندا ہے۔ جݙاں صحابیات کریم آقا ﷺ توں پردہ کیتا تے اللہ تعالیٰ اپݨے پاک کلام وچ ہر غیر محرم توں پردہ کرݨ دا حکم فرما ݙتا، تاں اڄ دی ایں روشن خیالی دی کیا حیثیت رہ ویندی ہے۔", "taaruf.058": "ایندے علاوہ! اساکوں اپݨے ٻالاں کوں جتھاں تئیں ممکن تھی سڳے موبائل فوناں دے منفی استعمال توں وی بچاوݨا پوسی۔ اڄ اوہو دور آ ڳیا ہے جیندے بارے آپ ﷺ فرمایا ہا جو فتنے گھراں دے دروازے بھن تے اندر داخل تھی ویسن۔ موبائل فون تے ٹی وی ای او فتنہ ہن جنہاں دے ذریعے گھر ٻیٹھے ٻالاں تئیں بے حیائی تے برائی دی رسائی ممکن تھی ڳئی ہے۔ اڄ واٹس ایپ سٹیٹس تے سوشل میڈیا تے ناچ گاݨے تے لہو و لعب دے سوا کجھ نظر نئیں آندا۔ خدارا! اپݨے آپ کوں تے اپݨے گھر آلیاں کوں اوں اڳ توں بچاؤ جیندا ٻالݨ بندے تے پتھر ہن۔", "taaruf.059": "تساں ایں کارِ خیر وچ ساݙے مددگار کیویں بݨ سڳدے ہو", "taaruf.060": "جے تساں ساݙی ایں تحریک دے اغراض و مقاصد نال متفق ہو تاں ساݙے نامزد کیتے ہوئے کارکناں نال رابطہ کر تے رکنیت فارم تے ڈاک لفافہ بالکل مفت گھن تے ایں تحریک دی ممبرشپ اختیار کر سڳدے ہو۔", "taaruf.061": "جے تساں باقاعدہ ممبر نئیں بݨݨ چاہندے تاں ایں تحریک دے پھیلاؤ کیتے ایں کتابچے وچ لکھیاں گزارشاں تے جتنی وی تھی سڳے انفرادی یا اجتماعی کوشش کر تے ساݙا ساتھ ݙیوو۔", "taaruf.062": "ماخذ: کتابچہ «تحریک اتباعِ سنت پاکستان کا تعارف اور اس کے مقاصد»", "baani.001": "بانی تے قائد دا تعارف", "baani.002": "تحریک اتباعِ سنت پاکستان دے بانی", "baani.004": "شروع دے حالات تے تعلیم", "baani.005": "تحریک اتباعِ سنت پاکستان دے بانی تے قائد، پیرِ طریقت کرامت علی بن محمد الیاس رزاقی دا تعلق گوٹھ محمد ابڑو، صوبہ سندھ نال ہے۔ نسب دے لحاظ نال آپ راجپوت قوم نال تعلق رکھدے ہن۔ ابتدائی تعلیم توں بعد 1983-84ء وچ ٹنڈو آدم نیو علی گڑھ کالج توں بی کام کیتا، تے ملازمت دے دوران ایم اے اکنامکس توں بعد ایل ایل بی کیتا۔", "baani.006": "ملازمت", "baani.007": "1985ء وچ آپ پاکستان پوسٹ وچ سینئر کلرک بھرتی تھئے۔ 2013ء وچ اسسٹنٹ سپرنٹنڈنٹ پوسٹل سروسز دی حیثیت نال، پیشوا دے حکم تے، ریٹائرمنٹ دے مقرر ویلے توں ݙہ سال پہلے ریٹائرمنٹ گھن تے سلسلہ عالیہ دی ترویج وچ رات ݙینہ مشغول تھی ڳئے۔", "baani.008": "بیعت تے خلافت", "baani.009": "مذہبی گھراݨہ ہووݨ پاروں شروع توں ای مذہب دے پاسے رجحان رہیا تے اپݨے بزرگاں دی تقلید وچ 1981ء وچ سلسلہ عالیہ نقشبندیہ دی عظیم روحانی شخصیت قطبِ عالم حضرت سائیں عبدالرزاقؒ دے دستِ اقدس تے بیعت تھئے۔ اوں ویلے کالج وچ پڑھدے ہن لیکن سر تے ہمیشہ ٹوپی رکھیندے تے نمازاں دی پابندی دا خاص خیال رکھیندے ہن۔ بعد وچ آپ اپݨے پیر و مرشد امام الذاکرین حضور محمد عظیم اللہ رزاقی نقشبندیؒ دی خدمت وچ ویلے کویلے کافی عرصہ گزاریا تے اُنہاں دی فیض بھری صحبت توں فیضیاب تھئے۔ نومبر 2006ء وچ پیر و مرشد آپ کوں اپݨی خلافت تے نیابت نال مشرف فرمایا۔", "baani.010": "دینی خدمات", "baani.011": "ہر سال وݙے پیمانے تے عرسِ مبارک دا اہتمام فرمیندے ہن۔ پیر بھراواں نال ودھ توں ودھ رابطہ، وعظ دے ذریعے دین دی تبلیغ تے ذکرِ حبیب ﷺ دیاں محفلاں کرواوݨ آپ دا طریقہ ہے۔ دین تے سلسلے دا پیغام پہنچاوݨ کیتے سوشل میڈیا دا مثبت استعمال وی کریندے ہن، تے خلفائے راشدین، اہلِ بیتِ اطہار تے بزرگانِ دین دے وصال دے ݙینہاں تے خاص کر آن لائن ٹرانسمیشن دا اہتمام کریندے ہن۔ ایں مشن دے تحت پاکستان دے وکھو وکھ علاقیاں دا سفر وی کریندے رہندے ہن۔", "baani.012": "آپ دے ڳوٹھ وچ 1972ء توں قائم مدرسہ عربیہ خالقیہ رزاقیہ دا انتظام وی آپ دے کول ہے۔ ایندے علاوہ اپݨے ڳوٹھ وچ دانش کدۂ عظیم مرکزِ علم و عرفان وی تعمیر کرایا ہے، جیڑھا مرکزی آفس تحریک اتباعِ سنت پاکستان، لائبریری مجدد الفِ ثانیؒ، زیرِ تعمیر مسجد سیدنا صدیقِ اکبرؓ، تے یتیم تے مستحق ٻالاں دی دینی تے عصری تعلیم تے کفالت کیتے مدرسے تے یتیم خانے تے مشتمل ہے۔ زالاں کیتے وی وکھرا مدرسہ بݨایا ہویا ہے۔ ٻئے پیر بھراواں کوں وی مدرسے قائم کرݨ دے نال نال ذکر تے نعت دیاں محفلاں دے اہتمام دی ترغیب ݙیندے ہن۔", "baani.013": "تربیت دا طریقہ", "baani.014": "آپ روایتی پیری مریدی توں ہٹ تے اپݨے مرشدینِ کاملین دے طریقے دے عین مطابق اپݨے مریداں تے ہر آوݨ آلے کوں ہمیشہ توحید، خوفِ خدا، اللہ تے توکل تے نبی کریم ﷺ دی محبت تے اتباع دا درس ݙیندے ہن۔ مدرسیاں دے قیام تے دینی تعلیم دے نال نال عصری تعلیم دا وی خاص انتظام کریندے ہن۔ مشائخِ عظام دے کشف تے کرامات تے مبنی کتاباں دی بجائے، جنہاں وچ یقیناً کافی حد تئیں مبالغہ وی ہوندا ہے، اُنہاں اُچے مرتبے آلے مشائخ دیاں اپݨیاں تصنیفاں پڑھݨ دی ہدایت کریندے ہن۔", "baani.015": "تصانیف", "baani.016": "سلسلہ عالیہ وچ ٻیا علمی ذوق پیدا کرݨ کیتے شریعت تے طریقت تے مبنی ݙہ توں ودھ کتاباں لکھ تے تالیف فرما چکے ہن۔ اپݨیاں لکھیاں ہوئیاں نعتاں تے مناقب دا مجموعہ «حروفِ ثناء» دے ناں نال چھپوا چکے ہن۔ ایں سلسلے کوں ٻیا ودھاوݨ کیتے رات ݙینہ کوشش وچ ہن۔", "baani.017": "تحریر: انجینئر شعیب عالم عظیمی مجددی", "baani.018": "صاحبزادگان دا تعارف", "baani.019": "صاحبزادہ اویس العظیم عظیمی", "baani.020": "آپ سندھ یونیورسٹی توں گریجویشن کیتی ہے تے ایں ویلے سندھ پولیس وچ وائرلیس آپریٹر دے طور تے خدمات سرانجام ݙیندے پئے ہن۔ آپ محفلاں وچ شریک تھیندے ہن تے وݙے پُرجوش انداز وچ نقابت فرمیندے ہن۔", "murshideen.001": "مرشدینِ کاملین دا تعارف", "murshideen.002": "شمس الکونین خواجہ محمد عبدالخالق نقشبندیؒ<span class=\"mk-hint\">تعارف پڑھو ▾</span>", "murshideen.003": "مونسِ بیوگان، دستگیرِ یتامیٰ، فاتحِ قادیانیت<br>شمس الکونین خواجہ محمد عبدالخالق شمس العرفانی نقشبندیؒ", "murshideen.004": "شروع دے حالات", "murshideen.005": "آپ شمس العرفان خواجہ قادر بخشؒ دے شہزادے تے شمس العارفین غوثِ زماں سائیں عبدالرزاقؒ دے پیر و مرشد ہن۔ آپ دا خطاب ابوسعد ہے۔ ۷ شوال ۱۲۷۰ھ / ۱۸۵۴ء جمعۃ المبارک دے ݙینہ صبحِ صادق دے ویلے جہانخیلاں وچ پیدا تھئے۔ آپ فرمیندے ہن جو ترائے سال دی عمر وچ میکوں فرشتیاں وچ قطبِ زماں سݙیا ویندا ہا، تے ست سال دی عمر وچ نبی کریم ﷺ تے سارے انبیائے کرام میکوں اپݨیاں زباناں مبارک چُسائیاں تے فرمایا جو اساں سارا علم تیکوں ݙے ݙتا۔ ہُݨیں آپ تقریباً ترائے سال دے ای ہن جو والد بزرگوار شمس العرفان خواجہ قادر بخشؒ شہادت پائی۔", "murshideen.006": "علمِ دین دا حصول", "murshideen.007": "علمِ حدیث کیتے سہارنپور وچ مولانا احمد علی محدثؒ دی خدمت وچ حاضر تھئے۔ مولانا حسین احمد کانپوریؒ تے پیر مہر علی شاہ گولڑویؒ آپ دے ہم سبق ہن۔ بعد وچ دہلی وچ مولوی کریم اللہ صاحبؒ تے مولوی سعید احمدؒ کولوں دینی علوم تے پوری طرح عبور حاصل کیتا۔ اللہ تعالیٰ دے فضل و کرم نال آپ علوم تے کمال دا ہک خزانہ ہن۔ جݙاں کہیں طرح دا کوئی مسئلہ آپ دے سامݨے پیش کیتا ویندا تاں وضاحت نال حوالیاں سمیت اینویں بیان فرمیندے جو وݙے وݙے مفتی حضرات حیران رہ ویندے۔ خلیفہ مولوی عبدالکریم جسری صاحبؒ اپݨی کتاب «خالقیہ» وچ لکھدے ہن جو خواجہ صاحبؒ موجودہ زمانے وچ کامل تے اکمل شخص ہن تے مولویاں دی جماعت دے ہک وݙے عالم ہن۔", "murshideen.008": "دین دے مبلغ دی حیثیت نال", "murshideen.009": "آپؒ اکثر کھڑے تھی تے تقریر فرمیندے ہن۔ آپؒ دے ابتدائی ملفوظات تے بیانات رشد و ہدایت، مذہب دی ترغیب تے اسلام دی اشاعت تے مبنی ہن۔ جݙاں اللہ تعالیٰ آپؒ کوں خدمتِ خلق دا حکم فرمایا تاں منصبِ خدمت تے فائز تھی تے مخلوق دی خدمت کیتے کمر ٻدھی، تے خاص طور تے ݙو خدمتاں یعنی بیواواں دا نکاح تے یتیماں تے مسکیناں دی خدمت سرانجام ݙتیاں۔", "murshideen.010": "مرشد دی طلب وچ سیاحت", "murshideen.011": "چھی سال توں پینتی سال دی عمر تئیں آپ دا ٻہوں سارا ویلا سفر وچ لنگھیا۔ ایں طلب وچ سارے ہندوستان، افغانستان، ایران تے عرب وغیرہ وچ سفر کیتا۔ (آپ فرمیندے ہن:) پیر پٹھان شاہ سلیمان تونسویؒ، کعبہ شریف وچ حاجی امداد اللہ مہاجر مکیؒ تے مدینہ شریف وچ صاحبان عبدالغنی تے مولانا محمد عمرؒ تے ٻئے بزرگاں دی خدمت وچ وی پہنچیا، مگر بیعت کیتے سوال ایں شرط تے کریندا ہم جو جے تساں میݙے سارے بدن توں اللہ، اللہ جاری کرا ݙیوو تاں بیعت تھیساں۔ مشائخ جݙاں اے سوال سُݨدے تاں ہتھ پچھاں چھک گھندے ہن۔", "murshideen.012": "سلسلۂ قادریہ وچ بیعت تے خلافت", "murshideen.013": "فرمیندے ہن: الٰہ آباد وچ شیخ احمد بخاری قادریؒ دی خدمت وچ پہنچیا تاں میکوں ݙیکھدیں ای فرمایا: «برو برو دیگر را بگیر» — ونڄو کوئی ٻئی راہ ݙیکھو۔ میں بے تاب تھی تے بھڄ تے قدماں نال چمبڑ ڳیا۔ ٻہوں شفقت نال میݙا سر چا تے سینے نال لایا، تے بیعت فرماوݨ کیتے جݙاں شیخ صاحبؒ اپݨے دستِ مبارک وچ میݙا ہتھ گھدا تے توجہ ݙتی تاں میں بے ہوش تھی ڳیا۔ اوں ویلے میݙے بدن دے ہر وال توں اللہ جاری ہا۔ ایکوں ای قرآن مجید وچ ذکرِ کثیر فرمایا ڳیا ہے تے ایکوں سلطان الاذکار آہدے ہن۔", "murshideen.014": "چھی مہینے دی خدمت توں بعد ہک ݙینہ سارے درویشاں دے سامݨے شیخ صاحب دستارِ خلافت میݙے سر تے ٻدھݨ چاہی تے فرمایا جو کیا اے ایں قابل ہے یا نئیں؟ کہیں دے جواب ݙیوݨ توں پہلے میں عرض کیتا جو ایں بھاری بوجھ دا چاوݨ تاں ٻہوں اوکھا لڳدا ہے، مگر ہتھ جوڑ تے التجا کریندا ہاں جو میݙی دلی مراد پوری تھی ونڄے۔ فرمایا: او کیا ہے؟ عرض کیتا جو اپݨا وجد بخش ݙیوو۔ آپؒ اے سُݨ تے سارے درویشاں کوں فرمایا: تساں لوک ہمیشہ آہدے ہاوے جو شیخ صاحب کوں ایں چھوہر نال ٻہوں محبت ہے، ہُݨ ݙساؤ جیڑھا سوال ایں چھوہر کیتا ہے کݙاہیں تہاݙے دل وچ وی اے خیال آیا؟ اے سُݨ تے سارے درویشاں کوں وجد آ ڳیا۔ فرمایا: رموز دانی ایندا ای ناں ہے۔ ول دستارِ خلافت اپݨے دستِ اطہر نال ٻدھ تے فرمایا: ونڄو سلسلۂ نقشبندیہ وچ بیعت کر تے اپݨے والد بزرگوار دا ناں روشن کرو، جتھاں تساں ہوسو اتھاں میں تہاݙے نال ہوساں۔", "murshideen.015": "سلسلۂ نقشبندیہ وچ بیعت تے خلافت", "murshideen.016": "شیخ صاحب آپ کوں جالندھر گھن ڳئے تے آپ دے والدِ بزرگوار شمس العرفانؒ دے پیشوا حاجی حافظ محمود جالندھریؒ کولوں سلسلۂ نقشبندیہ وچ بیعت کرایا۔ کیوں جو والد بزرگوار آپ کوں وصیت کیتی ہئی جو پہلے ست سال میݙے مزار تے ٻہݨا تے اپݨی تے میݙی والدہ دی خدمت کرݨی، ایں سانگے سلوکِ نقشبندیہ دی تکمیل دی غرض نال والد بزرگوار دے مزار مبارک تے روز حاضر تھیندے تے مزار مبارک توں روحانی تربیت پیندے رہے۔ آپؒ سلوکِ مجددیہ تھوڑے عرصے وچ طے فرمایا تے حاجی صاحبؒ آپ کوں دستارِ خلافت عطا فرمائی۔", "murshideen.017": "شمس الکونین دیاں احیائے سنت دیاں خدمتاں", "murshideen.018": "۱۔ بیواواں دا نکاح", "murshideen.019": "خواجہ صاحب اپݨی کتاب «سرمایۂ سہاگن» وچ فرمیندے ہن جو لڳاتار چار سال دی انتھک محنت توں بعد ۲۱ مارچ توں ۲۳ مارچ ۱۸۹۲ء مطابق ۱۳۰۹ھ قصبہ کلانور ضلع رہتک وچ جلسۂ اسلامیہ کرایا، جیندے وچ تیرہ ہزار ست سو پینسٹھ کرسیاں لائیاں ڳیاں تے ہک ٻہوں وݙا سٹیج سجایا ڳیا جیندے اُتے ڈپٹی کمشنر رہتک، وݙے وݙے افسراں تے علماء تے مشائخ کوں ٻلہایا۔ کلانور دے وݙے وݙے گھراݨیاں وچ بیواواں دے دھڑا دھڑ نکاح تھیوݨ لڳ پئے۔ تیرہ سو سال بعد ایں فرمانِ الٰہی «اپݨیاں بیواواں دے نکاح کرو» (القرآن) تے راجپوت قوم کوں تیار کر تے بیواواں دے نکاح دی مردہ سنت کوں زندہ کرݨ دا شرف حاصل کیتا۔ ایں توں پہلے راجپوت قوم ایکوں بے غیرتی دا کم سمجھدی ہئی۔ ٻہوں سارا روپیہ غریباں تے فقیراں وچ ونڈیا ڳیا تے دعوتِ ولیمہ وی سب کوں ݙتی۔", "murshideen.020": "معززین لوٹیاں وچ پاݨی تے لوݨ پوا تے عہد و پیمان گھدا جو اڄ توں اساں خوشی تے رضامندی نال ایں ہندوانہ تے کفریہ رسم کوں چھوڑیا تے دل جان نال خدا تے رسول ﷺ دا حکم منظور کیتا۔ ہُݨ ہمیشہ بیواواں دے نکاح کریندے رہسوں۔ جے ایں تے کوئی عمل نہ کریسی تاں سارے لوک اوندے نال ملݨ جُلݨ تے رشتہ ناتا چھوڑ ݙیسن۔ جیڑھا کوئی بیوہ دا نکاح کریسی اساں اوندے وچ خوشی نال شریک تھیسوں، جیویں کنواری چھوہر دے نکاح وچ شریک تھیندے ہیں، تے جیڑھا بندہ عیب تے طعنہ سمجھ تے شریک نہ تھیوے تاں برادری اونکوں کڈھ ݙیوے۔ جیویں اساں بیواواں دا ݙوجھا نکاح جاری کیتا ہے اینویں ای اساں شرعی پردہ جاری کریسوں، یعنی جیڑھے لوک غیر محرم ہن اُنہاں توں اپݨیاں نوہاں دھیاں کوں جتھاں تئیں ممکن ہوسی پردہ کراوݨ وچ ٻہوں کوشش کریسوں۔", "murshideen.021": "۲۔ یتیم پروری", "murshideen.022": "آپؒ جتھاں وی ویندے بیواواں دے نکاح دی تبلیغ دے نال نال یتیم پروری دی وی تلقین فرمیندے، کیوں جو یتیماں دا بیواواں نال ڈونگھا تعلق ہے۔ فرمیندے: یتیم پرور کوں جیڑھی بشارت نبی کریم ﷺ ݙتی ہے او کہیں عابد، زاہد، شہید یا کہیں وݙے توں وݙے نیک بندے کیتے نئیں ݙتی۔ فرمانِ مصطفیٰ ﷺ ہے: میں تے یتیم دی پرورش کرݨ آلا جنت وچ اینویں نال ہوسوں جیویں اے ݙو انگلیاں۔ آپ ﷺ انگشتِ شہادت تے اوندے نال آلی انگل کوں ملا تے اشارہ فرمایا۔ ایں سانگے آپؒ دے کول جو کجھ بچدا سب یتیماں تے بیواواں وچ ونڈ ݙیندے۔", "murshideen.023": "۱۵ جون ۱۹۰۵ء کوں یتیم خانہ خالقیہ تے انجمن خالقیہ قائم تھئے۔ ول قرآن پاک دی تعلیم دا بندوبست کیتا۔ بعد وچ ۱۹۰۶ء وچ پرائمری، ۱۹۱۴ء وچ مڈل تے ۱۹۲۵ء وچ ہائی سکول تے ول انٹر کالج منظور تھیا۔ انہاں اداریاں توں ہندو تے سکھ ٻال وی فیضیاب تھئے۔ مسلماناں، برہمناں، بنیاں، سکھاں تے چماراں دے ٻال وی پڑھدے ہن، تے افریقہ توں وی ترائے یتیم ٻال تعلیم کیتے آئے۔", "murshideen.024": "ایں طرح سید امیر حسین شاہ صاحب ساکن رحیم یار خان اُݨی مربعے زمین آپؒ دے ناں کرا ݙتی تاں جو آپؒ اپݨا پکا آستانہ تعمیر کراون۔ لیکن آپؒ او ساری زمین اپݨے یتیم خانے دے ناں کرا ݙتی تے فرمایا: اساکوں زمیناں دی لوڑ کائنی۔ آپؒ اپݨی رہائش ہمیشہ کانیاں دے چھپر آلے کچے مکان وچ ای رکھی لیکن یتیماں، مسافراں تے سکول دے ملازماں کیتے پکے مکان بݨوائے۔ جے کہیں افسر نال ملدے جیڑھا درِ دولت تے حاضر تھیندا تاں ہک ہتھ نال مصافحہ کریندے، جیڑھے افسر نذرانہ پیش کریندے او آپ نہ رکھیندے بلکہ یتیم خانے وچ جمع کرا ݙیندے تے اونکوں فرمیندے جو تہاݙا نذرانہ یتیم خانے وچ ایں سانگے جمع کرایا ہے جو ایندے بدلے خداوندِ کریم دنیا تے عقبیٰ وچ ہزار گُݨا عطا فرماوے۔ جݙاں کوئی مہمان مٹھائی وغیرہ گھن آندا تاں اتباعِ سنت وچ آپ اپݨے دستِ شفقت نال یتیماں تے درویشاں وچ ونڈ ݙیندے۔", "murshideen.025": "۳۔ تحفظِ ختمِ نبوت", "murshideen.026": "جݙاں مرزا غلام احمد قادیانی نبوت دا کوڑا دعویٰ کیتا تاں ۱۹۰۲ء وچ مباہلے کیتے ہزاراں اہلِ اسلام لاہور کٹھے تھئے۔ اہلِ سنت و جماعت دے پاسوں ترائے اصحاب — شمس الکونین خواجہ محمد عبدالخالقؒ، پیر مہر علی شاہ گولڑویؒ تے انور شاہ کشمیریؒ — چُݨے ڳئے۔ مرزا قادیانی مباہلے دی شرط رکھی جو میدان وچ سادہ قلم دوات رکھ ݙتی ونڄے، قدرت میݙی نبوت دی تصدیق کریسی۔ انہاں حضرات قبول کر گھدا۔ ݙوجھے ݙینہ میدانِ مباہلہ وچ لوک ٹولیاں دیاں ٹولیاں آوݨ لڳ پئے تے اے ترائے بزرگ حضرات وی پہنچ ڳئے، مگر مرزا قادیانی میدان وچ آوݨ دی بجائے قادیان بھڄ ڳیا۔", "murshideen.027": "دسمبر ۱۹۲۴ء وچ آپؒ روضۂ مبارک مجدد الفِ ثانیؒ سرہند شریف وچ ٹھہرے ہوئے ہن۔ ضلع رنگ پور بنگال دے مسلماناں خط لکھیا جو مرزا قادیانی دا پتر مرزا بشیر الدین قادیانی مسلماناں کوں مباہلہ کرݨ دا چیلنج ݙیندا پیا ہے، کیا آپؒ مباہلے کیتے تیار ہو؟ جواب ݙتا جو انہاں شرطاں تے مباہلے کیتے تیار ہاں: (۱) او مباہلے دی تاریخ دا آپ اعلان کرے۔ (۲) مباہلے دی جاہ ہندوستان دے کہیں وݙے شہر جیویں دہلی، لاہور، کلکتہ یا بمبئی وچ ہووݨی چاہیدی ہے۔ (۳) مباہلہ مجمعِ عام وچ ہووے۔ جݙاں مرزا اے شرطاں سُݨیاں تاں پنجاب بھڄ ڳیا۔", "murshideen.028": "۴۔ اوّل ویلے نماز دا اجراء", "murshideen.029": "۱۹۲۵ء وچ آپؒ خواب وچ ݙٹھا جو ہک مشہورِ زمانہ بزرگ تے سخت عذاب تھیندا پیا ہے۔ پتہ لڳا جو اے عذاب نمازاں دیر نال پڑھݨ تے جماعت چھوڑݨ پاروں تھیندا پیا ہے۔ اوں ویلے توں آپ ساریاں نمازاں، خاص کر فجر تے ظہر دی ادائیگی وچ ٻہوں جلدی فرماوݨ لڳ پئے، تے حنفی مسلک دے اوقات دے مطابق نماز دا ویلا شروع تھیندیں ای باجماعت نماز دا اہتمام فرمیندے ہن۔", "murshideen.030": "سورۃ الماعون وچ ارشادِ باری تعالیٰ ہے: <span class=\"kk-ar\" style=\"display:block\">فَوَيْلٌ لِّلْمُصَلِّيْنَ ۝ الَّذِيْنَ هُمْ عَنْ صَلَاتِهِمْ سَاهُوْنَ</span> — انہاں نمازیاں کیتے ویل یعنی جہنم دے ہک کھڈے دا عذاب ہے جیڑھے اپݨیاں نمازاں وچ غفلت کریندے ہن۔ نبی کریم ﷺ ارشاد فرمایا: اوّل ویلے نماز دی ادائیگی حق تعالیٰ دی خوشنودی دا باعث ہے۔", "murshideen.031": "امام غزالیؒ، سیدنا شیخ عبدالقادر جیلانیؒ، امامِ ربانی مجدد الفِ ثانیؒ تے شاہ غلام علی دہلویؒ جیہے اُچے مرتبے آلے مشائخ وی اوّل ویلے نماز ادا فرمیندے ہن تے اپݨے مریداں کوں وی ایندی تلقین فرمیندے ہن۔ نال ہر سمجھدار بندہ اے ڳالھ چنگی طرح سمجھ سڳدا ہے جو رب دا حکم تھی ونڄݨ توں بعد نماز دی ادائیگی وچ بغیر شرعی عذر دے دیر کرݨ دعویٔ محبت توں پرے تے حکم عدولی دے نیڑے ہے، جݙاں جو بندہ اوہو محبوب ہوندا ہے جیڑھا ویلا تھیندیں ای اپݨے رب دے حضور سجدے وچ ڈھہ پووے۔ ایں سانگے اوّل ویلے نماز ادا کرݨ دی کوشش کرݨی چاہیدی ہے۔", "murshideen.032": "وصال مبارک", "murshideen.033": "تقریباً رات دے ہک وڄے سائیں صاحبؒ کوں جڳایا تے فرمایا: میکوں وضو کرا تے تہجد دے نفل پڑھاؤ۔ نفلاں توں بعد سجدے وچ سر رکھ تے دعا منگی: اے اللہ! میکوں جان کنی دی تکلیف نہ ݙیویں تے سجدے دی حالت وچ شہادت دا درجہ عطا فرماویں۔ دعا توں بعد فرمایا: عبدالرزاق! ہُݨ میکوں سخت بے چینی ہے، دٻیندے رہو۔ اینویں فجر دا ویلا تھی ڳیا، آپؒ وضو کر تے فجر دیاں سنتاں ادا کیتیاں۔ جماعت کھڑی تھی ڳئی۔ آپؒ دے نال سید دین علی شاہؒ، سائیں عبدالرزاقؒ تے مولوی سراج الدین مقتدی ہن۔ ݙوجھی رکعت دے آخری سجدے وچ یکدم ساری چھت ڈھہ پئی، تے ۷ محرم الحرام ۱۳۵۰ھ کوں ۸۰ سال دی عمر مبارک وچ آپؒ اپݨے خالقِ حقیقی نال ونڄ ملے۔", "murshideen.034": "شمس العارفین سائیں عبدالرزاق خالقی نقشبندیؒ<span class=\"mk-hint\">تعارف پڑھو ▾</span>", "murshideen.035": "شمس العارفین، سراج السالکین<br>قطبِ عالم حضرت سائیں عبدالرزاق خالقی نقشبندیؒ", "murshideen.036": "کشف تے کرامات تاں تلے درجے دی ڳالھ ہے، اصل اتباعِ سنت تے شریعتِ مطہرہ دی پابندی ہے کیوں جو مریداں پیشوا دے عمل کوں ݙیکھ تے اوندی پیروی کرݨی ہوندی ہے۔ (شمس العارفینؒ)", "murshideen.037": "اکثر فرمایا کریندے ہن: شریعت ٻیج ہے، جے ٻیج ای خراب ہووے تاں رکھ کیویں ٹھیک تھیسی۔ پہلوں وی شریعت ہے تے چھیکڑ وی شریعت۔ جے کوئی ہوا وچ اُݙدا ہویا وی آوے پر شریعت کوں وال برابر وی چھوڑݨ والا ہووے تاں اوہ جادوگر تھی سڳدا ہے پر اللہ والا نئیں تھی سڳدا۔", "murshideen.038": "ولادت باسعادت", "murshideen.039": "آپؒ دے فرمودات مطابق آپ دی ولادت باسعادت ۱۸۹۰ء وچ تھئی۔ ولادت توں بعد آپ دی ݙاݙی نیک بختی تے لمی عمر کیتے آپ کوں مسجد وچ بھجوا ݙتا۔ آپ فرمایا کریندے ہن جو اللہ تعالیٰ دا احسان ہے جو ساری عمر مسجداں وچ ای گزر ڳئی۔", "murshideen.040": "ابتدائی تعلیم", "murshideen.041": "جݙاں آپ دی عمر پنج چھی سال تھئی تاں اوں ویلے ای نمازِ پنجگانہ تے ست اٹھ سال دی عمر توں نمازِ تہجد پابندی نال ادا کرݨ شروع کر ݙتی جیہڑی اللہ دے فضل نال چھیکڑی دم تئیں قضا نئیں تھئی۔", "murshideen.042": "جݙاں تساں نمازِ تہجد شروع کیتی، آپ دی عمر بس ست سال ہئی", "murshideen.043": "نہ کوئی تکبیرِ اولیٰ کھنجی نہ کوئی نماز قضا تھئی، میݙے سائیںؒ پیا، تیݙی کیا ڳالھ ہے", "murshideen.044": "ابتدائی تعلیم مدرسہ کلانور وچ حاصل کیتی۔ ݙوجھی جماعت توں بعد مجذوبانہ حالت پاروں سکول چھوڑ ݙتا۔ قرآن شریف امامِ مسجد حافظ عبدالرحمٰن صاحب کولوں پڑھیا۔", "murshideen.045": "خواجہ صاحبؒ دی خدمت وچ حاضری", "murshideen.046": "بزرگانِ دین فرمیندے ہن جو جیہڑا کوئی ایہ چاہوے جو اوہ اللہ دا مقرب بݨ ونڄے تاں اوہ اولیاء اللہ دی صحبت اختیار کرے۔", "murshideen.047": "ایں طرحاں جݙاں آپ دی عمر مبارک ٻارھاں سال تھئی تاں آپؒ دے والد آپ کوں خواجہ صاحبؒ دی خدمت وچ گھن ڳئے۔ خواجہ صاحبؒ آپ کوں جھولی وچ چاتا تے پیار کیتا۔ آپؒ دے والد صاحب عرض کیتی جو ایہ ہر ویلے روندا تے قرآن شریف پڑھدا رہندا ہے تے کہیں نال ڳالھ نئیں کریندا، اتنا تھی ونڄے جو اینکوں کھاوݨ پیوݨ، کپڑے پاوݨ تے ٻولݨ دا شعور آ ونڄے۔ خواجہ صاحبؒ فرمایا: شادی وی تھیسی، اولاد وی تھیسی، نوکری وی کریسی تے سردار وی تھیسی، ایندا ناں نبی کریم ﷺ دے مقبول بندیاں دی فہرست وچ درج تھی چکا ہے۔ آپؒ آپ فرمیندے ہن جو خواجہؒ صاحب دی نگاہِ فیض نال میݙے اُتے جیہڑا معاملہ گزریا اوہ بیان توں باہر ہے۔ ایں دوران ای آپؒ خواجہ صاحبؒ کولوں بیعت تھی ڳئے ہن۔", "murshideen.048": "منازلِ سلوک طے کرݨ", "murshideen.049": "حضور سائیںؒ جی فرمایا: میں ۴۰ سال خواجہ صاحبؒ دی خدمت وچ رہیا پر اُنہاں دے سامݨے کݙاہیں نہ ٻولیا۔ ہک ݙینہہ خواجہ صاحبؒ میݙی پٹھ اُتے سوار ہن تے نعلین مبارک سید دین علی شاہ صاحبؒ چاتی ہوئی ہن۔ آپؒ روندیاں ہویاں ایویں دعا فرمائی:", "murshideen.050": "یا اللہ! جتنا میں ایں عبدالرزاق توں خوش ہاں توں وی اُتنا ای خوش تھی ونڄ، جتنی ایں میݙی خدمت کیتی ہے مخلوق وی ایندی اُتنی ای خدمت کرے۔", "murshideen.051": "ہک واری سید دین علی شاہ صاحبؒ خواجہ صاحبؒ کوں عرض کیتی جو حضور! جے عبدالرزاق فوج وچ ہوندا تاں اڄ ایہ وی سردار ہوندا۔ آپؒ اُٹھ تے ٻہہ ڳئے تے فرمایا: شاہ جی! تساں کیا سمجھدے ہو، فوجی سردار تاں ایندے پیراں وچ رُلسن۔ آپؒ آپ فرمیندے ہن جو نہ تاں میݙے وچ علم ہے، نہ میں تسبیح پھیری تے نہ ورد وظیفے کیتے، ایہ سب خواجہؒ صاحب دی صحبت، نگاہ تے دعا و برکت دا فیض ہے۔ میں کݙاہیں خواجہ صاحبؒ دے سامݨے اکھ چا تے وی نہ ݙٹھا تے نہ کݙاہیں آپؒ دے سامݨے ٻولیا۔", "murshideen.052": "توں چھتی سال شیخ دے کول رہیا، شیخ دا دیدار ای تیݙا وظیفہ ہا", "murshideen.053": "چھیکڑی ساہ تئیں تساں جدا نہ تھئے، میݙے سائیں پیا، تیݙی کیا ڳالھ ہے", "murshideen.054": "یتیماں دی پرورش", "murshideen.055": "یتیماں دی پرورش وچ آپ دا کوئی ثانی کائنا ہا۔ معاشرے دے ٹھکرائے ہوئے مصیبت زدہ یتیم ٻالاں دی امداد تے مدد کیتے ہر ویلے بے چین تے مضطرب ݙسدے ہن۔", "murshideen.056": "ایں سلسلے وچ حافظ علیم الدین صاحب بیان کیتا جو ۱۹۶۵ء وچ حضور سائیںؒ جی حج توں واپس تشریف گھن آئے تاں اساں ٻہوں سارے بندے دیپالپور شریف توں حضور دے استقبال کیتے اوکاڑہ سٹیشن تے آئے۔ موج دین رزّاقی گلاب دے پھلاں دا ہار گھن تے آیا۔ اساں حضور کوں گݙی توں لہایا۔ موج دین حضور دے ڳل وچ ہار پاوݨ چاہیا پر حضور اوہ ہار موج دین دے ڳل وچ پا ݙتا تے فرمایا: فضول خرچی ہے، ݙکھاوا ہے۔ اتنے پیسے یتیم خانے وچ جمع کرا ݙیندے تاں بہتر ہا۔", "murshideen.057": "فرمایا کریندے ہن جو یتیم نال ایجھا سلوک کرݨا چاہیدا ہے جو اونکوں یتیمی دا ذرا وی احساس نہ تھیوے۔ جے بھیک منگوا تے پالݨا ہے تاں وت اوہ آپ وی آپݨا ٹِڈھ پال سڳدے ہن، تہاݙا کیا احسان؟ بلکہ یتیماں کولوں چندہ منگواوݨ تے وت آپ وی ورتݨ ݙوہیں حرام ہن۔", "murshideen.058": "یتیم ٻالاں دی مستقل بحالی کیتے ملک دیاں مختلف جاہیں تے لکھاں روپے دے خرچے نال دار الشفقت دے ناں توں یتیم خانے تے اُنہاں دے نال مسجداں تے تعلیمی ادارے بݨوائے۔ اُنہاں یتیم خانیاں وچ رہݨ والے سینکڑاں یتیم تے لاوارث ٻالاں کوں دینی تعلیم دے نال نال عصری تے ووکیشنل تعلیم وی ݙتی ویندی ہئی تے ایویں اُنہاں کوں معاشرے دا بوجھ بݨݨ دی بجائے عزت تے وقار والی زندگی گزارݨ دے قابل بݨایا ویندا ہا۔ ایہ ادارے حکومت کول باقاعدہ رجسٹرڈ تے منظور شدہ ہن تے اُنہاں وچ بورڈ دی نگرانی ہیٹھ امتحان گھدے ویندے ہن۔", "murshideen.059": "آپؒ آپݨی جدّی زرعی زمین آپݨی اولاد وچ ونڈ ݙتی ہئی تاں جو اوہ عزت نال گزارہ کر سڳن تے باقی ساری شہری جائیداد یتیم خانے دے ناں ہبہ فرما ݙتی۔ اتھوں تئیں جو وصال توں پہلے نذرانے دا ہک لکھ تیئی ہزار روپیہ وی یتیم خانے دے فنڈ وچ جمع کروا ݙتا تے فرمایا: اولاد لائق تھئی تاں آپ بݨا گھنسی، نالائق تھئی تاں پہلا وی ضائع کر ݙیسی۔ اللہ دی راہ وچ خرچ کرݨا چاہیدا ہے جیہڑا اڳوں کم آوے۔", "murshideen.060": "خطاب سراج السالکین", "murshideen.061": "رسالدار محمد لقمان رزّاقی صاحب بیان کریندے ہن جو ذہن وچ اکثر ایہ سوال آندا ہا جو اللہ تعالیٰ دے خاص بندیاں کوں مختلف قسم دے خطاب کیویں مل ویندے ہن۔ ہک ݙینہہ نمازِ فجر توں کجھ دیر پہلے میں مسجد وچ ٻیٹھا ہویا ہم جو اونگھ آ ڳئی۔ ݙٹھا جو امامِ ربانی مجدد الفِ ثانیؒ تے قبلۂ عالم حضور سائیںؒ جی مسجد دی محراب دے سامݨے کھڑے ہن۔ حضرت مجدد صاحبؒ سائیںؒ صاحب کوں سینے نال لایا تے وت فرماوݨ لڳے: آؤ تہاکوں سراج السالکین دا ٹھپہ لا ݙیووں۔ بس وت اکھ کھل ڳئی تے ایویں سوال دا جواب مل ڳیا۔", "murshideen.062": "خطاب شمس العارفین", "murshideen.063": "آپؒ ہک واری سید جماعت علی شاہؒ دے خلیفہ چراغ علی شاہؒ، جنہاں دا مزارِ مبارک لاہور والٹن وچ ہے، دے کول مرالہ شریف تشریف گھن ڳئے۔ شاہ صاحبؒ آپݨی پڳ لہا تے ڳل وچ پا گھدی تے ݙوہیں ٻانہہ کھڑیاں کر تے فرماوݨ لڳے جو میں کیا ݙساں جو میݙے گھر کوݨ آ ڳئے ہن، شریعت منع کریندی ہے، ایہ سمجھو جو کیڑی دے گھر نرائن آ ڳئے ہن۔ ایں تے حضور سائیںؒ جی فرمایا: شاہ جی ٻہوں وݙے درویش ہن، دنیا دے چوتھے حصے دے مالک ہن۔ شاہ جی فرماوݨ لڳے جو جی آپؒ میݙا بھید کھول ݙتا، معافی منگدا ہاں، میں وی ہݨ رہ نئیں سڳدا، میں وی آپ دا بھید کھولیندا پیا ہاں، آپؒ ساری دنیا دے مالک ہو تے ایں ویلے ہک ای ہک ہو۔ ہک واری شاہ صاحبؒ فرمایا جو حضور سائیںؒ جی دا خطاب شمس العارفین ہے۔", "murshideen.064": "وصالِ پُرملال", "murshideen.065": "آپؒ بواسیر دے آپریشن کیتے کنعان ٹرسٹ ہسپتال لاہور وچ داخل ہن جتھاں آپ دی منجی پہلی صف وچ وچھا ݙتی ویندی، مٹی نال تیمم کروایا ویندا تے آپؒ لیٹے لیٹے اشاریاں نال نماز باجماعت ادا فرمیندے ہن۔ ۲۴ مارچ ۱۹۸۲ء کوں ولا کنعان ٹرسٹ ہسپتال لاہور وچ داخل تھئے۔", "murshideen.066": "آخر منگل دی رات آپ کوں استغراق تھیا تے لڳ بھڳ ۲۰ گھنٹے استغراق دی حالت وچ رہ تے بدھ دے ݙینہہ ۴ وڄے شام، ۳۱ مارچ ۱۹۸۲ء بمطابق ۴ جمادی الثانی ۱۴۰۳ھ کوں، لڳ بھڳ ۹۵ ورھیاں دی عمرِ مبارک وچ آپݨے خالقِ حقیقی نال ونڄ ملے۔ وصال ویلے آپݨے ݙوہیں ہتھاں دیاں شہادت دیاں انگلاں چا گھدیاں تے نال ای زبانِ مبارک توں اسمِ ذات اللہ نکلیا۔ وصال توں بعد سب ݙٹھا جو قلبِ سلیم ذکرِ الٰہی وچ حرکت کریندا پیا ہا۔ وصالِ مبارک دے فوراً بعد ریڈیو پاکستان لاہور توں ایہ اعلان تھیا: آفتابِ طریقت لڳ بھڳ ہک صدی تئیں جگمگا تے اڄ بدھ ۳۱ مارچ ۱۹۸۲ء بمطابق ۴ جمادی الثانی ۱۴۰۳ھ کوں غروب تھی ڳیا۔", "murshideen.067": "جسدِ مبارک کوں غسل ݙتا ڳیا تے وصیت مطابق اوں چادر وچ ولھیٹیا ڳیا جیہڑی شہادت ویلے خواجہ صاحبؒ دے جسمِ مبارک اُتے ہئی، تے خواجہ صاحبؒ دے موئے مبارک وی آپؒ دے کفن وچ رکھے ڳئے۔ ٻہوں وݙے ہجوم پاروں آپ دی نمازِ جنازہ ترے واری پڑھائی ڳئی۔ جمعہ دے ݙینہہ ۲ اپریل کوں وصیت مطابق جسدِ مبارک کوں لکڑ دے صندوق وچ معلق حالت وچ رکھ تے سپردِ خاک کر ݙتا ڳیا۔", "murshideen.068": "خلفاءِ کرام تے سجادگان", "murshideen.069": "آپؒ دے مشہور خلفاءِ کرام ترے ہن جنہاں دے اسمائے گرامی ہیٹھ ݙتے ڳئے ہن:", "murshideen.070": "۱۔ امام الذاکرین حضور سائیں محمد عظیم اللہ رزّاقی نقشبندیؒ، دربارِ عالیہ عظیم نگر شریف ضلع بہاولنگر۔<br>۲۔ بے حد سوہݨے خواجہ نور احمد خاں رزّاقی نقشبندیؒ، دربارِ عالیہ لالہ موسیٰ شریف ضلع گجرات۔<br>۳۔ ایڈووکیٹ حضور محمد شریف رزّاقی نقشبندیؒ، دربارِ عالیہ سیل گاؤں ضلع پاکپتن شریف۔", "murshideen.071": "آپؒ دے ݙو شہزادے ہن، جنہاں دے اسمائے گرامی ہیٹھ ݙتے ڳئے ہن:", "murshideen.072": "۱۔ صاحبزادہ فقیر محمد رزّاقی نقشبندی، اللہ تعالیٰ آپ دا سایہ دیر تئیں ساݙے سراں تے قائم رکھے۔<br>۲۔ صاحبزادہ بلال احمد رزّاقی نقشبندیؒ۔ آپ دا وصال ۲۰۲۵ء وچ تھیا ہا۔ اللہ تعالیٰ آپ دے درجات بلند فرماوے۔", "murshideen.073": "امام الذاکرین سائیں محمد عظیم اللہ رزّاقی نقشبندیؒ<span class=\"mk-hint\">تعارف پڑھو ▾</span>", "murshideen.074": "امام الذاکرین، سراج السالکین، قطبِ دوراں<br>مظہرِ نورِ خدا قبلۂ عالم سائیں محمد عظیم اللہ رزّاقی نقشبندیؒ", "murshideen.075": "ولادت تے ٻالپݨ", "murshideen.076": "شناختی کارڈ مطابق آپؒ یکم جنوری ۱۹۳۴ء کوں انڈیا دے موضع سیہوانی ضلع حصار وچ راجپوت گھرانے دے ہک نیک سیرت فرد حاجی حسین علی صاحبؒ دے گھر پیدا تھئے۔ والدہ ماجدہ دا تعلق ڈھنکوٹ دے محلہ میر خان نال ہا جنہاں دا کنبہ ایں ویلے گوٹھ محمد ابڑو وچ رہندا ہے۔ آپ ٻالپݨ وچ کافی بیمار رہندے، چپ رہندے یا وت روندے رہندے ہن۔", "murshideen.077": "بیعتِ طریقت", "murshideen.078": "سورۃ المائدہ وچ ارشادِ باری تعالیٰ ہے: <span class=\"kk-ar\" style=\"display:block\">يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اتَّقُوا اللّٰهَ وَابْتَغُوْٓا اِلَيْهِ الْوَسِيْلَةَ وَجَاهِدُوْا فِيْ سَبِيْلِهٖ لَعَلَّكُمْ تُفْلِحُوْنَ</span> اے ایمان والو! اللہ توں ڈرو تے اوندی طرف وسیلہ ڳولو تے اوندی راہ وچ مجاہدہ کرو تاں جو تساں فلاح پاؤ۔ (۳۵)", "murshideen.079": "آپݨے بیعت تھیوݨ دا واقعہ ساݙے پیشوا آپ ایویں بیان فرمایا کریندے ہن جو جݙاں میں پنجویں جماعت وچ پڑھدا ہم تاں فوجی بھرتی کرݨ کیتے آئے تاں میں وی ٻئے چھوریں نال بھرتی تھی ڳیا۔ اُنہاں ݙینہاں وچ ڈونگہ بونگہ وچ راؤ مراتب علی دے ڈیرے تے حضور سائیںؒ جی تشریف فرما ہن۔ میں زیارت کیتے حاضر تھیا تاں سائیںؒ جی اوں ویلے ای میکوں بیعت فرما گھدا۔", "murshideen.080": "بعد وچ حضور سائیںؒ جی سونڈھا شریف تشریف گھن آئے تاں میݙی والدہ آپ کوں ݙیکھدیاں ای آکھیا جو ایہ تاں اوہے بزرگ ہن جیہڑے انڈیا وچ عامل میکوں میݙے نونہہ وچ ݙکھائے ہن۔ میݙی والدہ راہ وچ کھڑی تھی ڳئی تے سائیںؒ جی کوں عرض کیتی: میں عظیم اللہ تاں ٻہوں پہلے ای آپ کوں ݙے ݙتا ہا۔ سائیںؒ جی فرمایا: ہا، ایہ میݙا ای ہے۔ ۱۹۵۵ء وچ حضور سائیںؒ جی میکوں آپݨے نال دیپالپور شریف گھن ڳئے تے ہک ݙینہہ کپڑے دھوندیاں ہویاں گیرو رنگ دا ڈھیلا منگوا تے آپݨے کپڑیاں کوں رنگݨ دے نال میݙے کپڑیاں کوں وی گیرو رنگ نال رنگ ݙتا۔", "murshideen.081": "منصبِ خلافت", "murshideen.082": "حضور سائیںؒ جی دی طرفوں خلافت دا منصب عطا تھیوݨ دا واقعہ آپؒ ایویں بیان فرمیندے ہن: حضور سائیںؒ جی دیپالپور شریف مسجد وچ تشریف فرما ہن۔ میں صبح حلقۂ ذکر توں بعد مسجد دے ویہڑے وچ ونڄ تے کݨک صاف کرݨ لڳ پیا۔ حضور سائیںؒ جی مراقبے توں بعد میکوں یاد فرمایا تے آپݨی سڄی ٻانہہ دی ولھیٹ وچ گھن تے ارشاد فرمایا: اللہ اللہ کرایا کرو۔ میں عرض کیتی جو حضور سب لوک خوب اللہ اللہ کریندے ہن۔ فرمایا: پہلے اِنہاں سبھ کوں مرید کیتا کرو، بعد وچ اللہ اللہ سکھایا کرو۔ اوں ویلے میݙے اُتے ٻہوں خوف طاری تھیا، سارے جسم تے مُڑھکا آ ڳیا۔ فرمایا: خواجہ صاحبؒ میکوں وی ایویں فرمایا ہا جو ایویں توجہ ݙیا کرو تے ایویں اللہ اللہ کرایا کرو۔", "murshideen.083": "خطاب امام الذاکرین", "murshideen.084": "ناچیز مؤلف آپݨے پنڈ وچ حضور سائیںؒ جی دے سالانہ عرس مبارک دے سلسلے وچ اشتہار چھپواوݨے ہن۔ ایں سوچ وچ سم ڳیا جو حضور قبلۂ عالمؒ دے نامِ مبارک نال آپ دی شان دے لائق کیا لقب لکھواواں۔ خواب وچ ݙٹھا جو ناچیز حضور سائیںؒ جی دی قبرِ انور دے کول کھڑا ہے تے آپؒ دے مزار دے آلے دوالے جتھوں تئیں میݙی نظر پہنچدی ہئی فرش توں عرش تئیں نور ای نور نظر آندا ہا تے آپ دی قبرِ انور توں آواز آئی: عظیم اللہ! امام الذاکرین ہے۔", "murshideen.085": "وصال مبارک", "murshideen.086": "آپ کافی عرصہ بیمار رہݨ توں بعد ۱۴ جمادی الاوّل ۱۴۳۴ھ بمطابق ۲۷ مارچ ۲۰۱۳ء بدھ دے ݙینہہ صبح اٹھ وڄے سونڈھا شریف وچ ذکر اللہ کریندیاں ہویاں لڳ بھڳ ۸۳ ورھیاں دی عمر وچ آپݨے خالقِ حقیقی نال ونڄ ملے۔ آپ دی نکی بھیݨ حکومت بی بی دے آکھݨ مطابق وصال دے نیڑے آپؒ فرمایا جو حضور سائیںؒ جی میݙے کول ٻیٹھے ہن۔", "murshideen.087": "آپ دی تدفین ۲۹ مارچ جمعۃ المبارک دے ݙینہہ بہاولنگر روڈ تے ڈونگہ بونگہ توں کجھ پہلے سورج گنج موڑ تے آپ دی مسجد دے ویہڑے دے نیڑے کیتی ڳئی، جتھاں ایں ویلے سائیں حضورؒ دے مزارِ اقدس دے ڈیزائن تے آپ دا روضۂ اقدس بݨدا پیا ہے۔ مخلوقِ خدا ݙینہہ رات آپؒ توں فیض پیندی پئی ہے۔", "murshideen.088": "تصویراں تے مزاراں دی تفصیل جلدی شامل کیتی ویسی، ان شاء اللہ۔", "mubalighin.001": "مبلغین دا تعارف", "mubalighin.002": "تصویراں تے ویڈیوز جلدی شامل کیتیاں ویسن، ان شاء اللہ۔", "markaz.001": "مرکزی مرکز", "marakiz.001": "ذیلی مرکز تے مدرسے", "marakiz.002": "اسلام پور", "marakiz.003": "کوٹلی نجابت", "marakiz.004": "وہاڑی", "marakiz.005": "کوٹ مصری خان", "marakiz.006": "مہاجر گوٹھ", "marakiz.007": "گوٹھ ابڑو", "marakiz.008": "35 چک", "marakiz.009": "راؤ گڑھ", "marakiz.010": "باقی مرکزاں تے مدرسیاں دی تفصیل جلدی شامل کیتی ویسی، ان شاء اللہ۔", "bayanat.001": "بیانات", "bayanat.002": "کہیں بیان تے دباؤ — ویڈیو یوٹیوب تے چلسی۔", "kutub.001": "کتاباں", "kutub.002": "حرف حرف تاثیر", "kutub.003": "<span>مؤلف:</span> بانی تے قائد تحریک اتباعِ سنت پاکستان، مذہبی سکالر کرامت علی رزّاقی عظیمی مجددی نقشبندی <span class=\"lat\">(M.A, L.L.B)</span>", "kutub.004": "<span>معاونت:</span> انجینئر شعیب عالم عظیمی مجددی (ایم اے علومِ اسلامیہ)، <span class=\"lat\">HOD</span> الیکٹریکل ٹریڈ، گورنمنٹ ٹیکنیکل ٹریننگ انسٹی ٹیوٹ لودھراں", "kutub.005": "صفحے: <span class=\"lat\">136</span>  • اشاعت: اکتوبر <span class=\"lat\">2026</span>", "kutub.006": "تحریک اتباعِ سنت پاکستان دا تعارف تے ایندے مقاصد", "kutub.007": "ساݙا مقصد شریعت تے سنت دا فروغ", "kutub.008": "<span>مؤلف:</span> بانی تے قائد تحریک، پیرِ طریقت کرامت علی رزّاقی عظیمی نقشبندی <span class=\"lat\">(M.A, L.L.B)</span>", "kutub.009": "صفحے: <span class=\"lat\">19</span>", "kutub.010": "صراط الفلاح فی الدنیا والآخرۃ", "kutub.011": "دنیا تے آخرت وچ کامیابی دا راہ", "kutub.012": "<span>مؤلف:</span> بانی تے قائد تحریک اتباعِ سنت پاکستان، پیرِ طریقت کرامت علی رزّاقی عظیمی نقشبندی <span class=\"lat\">(M.A, L.L.B)</span>", "kutub.013": "<span>معاونت:</span> انجینئر شعیب عالم عظیمی مجددی (ایم اے علومِ اسلامیہ)، <span class=\"lat\">HOD</span> الیکٹریکل ٹریڈ، گورنمنٹ ٹیکنیکل ٹریننگ انسٹی ٹیوٹ لودھراں", "kutub.014": "صفحے: <span class=\"lat\">83</span>  • اشاعت: مارچ <span class=\"lat\">2019</span>", "kutub.015": "دستورِ طریقت", "kutub.016": "جیہڑی راہِ سلوک دے ناں نال مشہور ہے", "kutub.017": "<span>مؤلف:</span> بانی تے قائد تحریک اتباعِ سنت پاکستان، پیرِ طریقت، شیرِ مجدد بدرالہدیٰ کرامت علی رزّاقی عظیمی نقشبندی <span class=\"lat\">(M.A, L.L.B)</span>", "kutub.018": "<span>معاونت:</span> انجینئر شعیب عالم عظیمی مجددی (ایم اے علومِ اسلامیہ)، <span class=\"lat\">HOD</span> الیکٹریکل ٹریڈ، گورنمنٹ ٹیکنیکل ٹریننگ انسٹی ٹیوٹ لودھراں", "kutub.019": "صفحے: <span class=\"lat\">129</span>  • اشاعت: اکتوبر <span class=\"lat\">2016</span>", "gallery.001": "تصویراں دی گیلری", "bait.001": "بیعت تے طریقت", "bait.002": "بیعتِ طریقت", "bait.003": "سورۃ المائدہ وچ ارشادِ باری تعالیٰ ہے: <span class=\"kk-ar\" lang=\"ar\" style=\"display:block\">يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اتَّقُوا اللّٰهَ وَابْتَغُوْٓا اِلَيْهِ الْوَسِيْلَةَ وَجَاهِدُوْا فِيْ سَبِيْلِهٖ لَعَلَّكُمْ تُفْلِحُوْنَ</span> اے ایمان والو! اللہ توں ڈرو تے اوندی طرف وسیلہ ڳولو تے اوندی راہ وچ مجاہدہ کرو تاں جو تساں فلاح پاؤ۔ (۳۵)", "bait.004": "شاہ ولی اللہ محدثِ دہلوی ارشاد فرمیندے ہن جو ایں آیت وچ وسیلہ توں مراد مرشدِ کامل ہے۔", "bait.005": "سورۃ لقمان وچ ارشادِ باری تعالیٰ ہے: <span class=\"kk-ar\" lang=\"ar\" style=\"display:block\">وَاتَّبِعْ سَبِيْلَ مَنْ اَنَابَ اِلَيَّ</span> تے اوندی راہ دی پیروی کرو جیں میݙی طرف رجوع کیتا۔ (۱۵)", "bait.006": "بیعتِ طریقت تے ارادت بارے سیدنا عبادہ بن صامت انصاریؓ فرمیندے ہن جو اساں رسول اللہ ﷺ نال ہر آسانی تے اوکھ، ہر خوشی تے ناگواری وچ آپ ﷺ دا حکم سݨݨ تے اطاعت کرݨ تے آپ ﷺ دے کہیں حکم وچ چون و چرا نہ کرݨ تے بیعت کیتی۔ (بخاری کتاب الاحکام)", "bait.007": "حجۃ الاسلام امام غزالیؒ فرمیندے ہن جو انبیاء کرام علیہم السلام توں سوا کوئی وی ظاہری تے باطنی بیماریاں توں خالی نئیں۔ ایں سانگے اُنہاں بیماریاں کوں دور کرݨ کیتے صوفیاں دے نال طریقت وچ داخل تھیوݨ ضروری ہے۔ جیویں علمِ طب وچ ایہ ڳالھ طے ہے جو طب دیاں کتاباں پڑھݨ دے باوجود کوئی آپ ای آپݨا علاج نئیں کر سڳدا بلکہ ایندے کیتے کوئی طبیب چاہیدا ہے۔ بالکل ایویں دل تے نفس دیاں بیماریاں دا علاج وی آپ ای نئیں کیتا ونڄ سڳدا، اِنہاں کیتے وی ہک مرشدِ کامل دی لوڑ ہے۔", "bait.008": "سیدنا عبدالقادر عیسیٰؒ شاذلی فرمیندے ہن جو نبی کریم ﷺ دے صحابہ کرامؓ وی صرف قرآن پڑھݨ نال آپݨے نفساں دا علاج نئیں کر سڳدے ہن، اوہ وی حاذقِ کونین ﷺ دے شفا خانے نال جڑے ہوئے ہن تے آپ ﷺ اُنہاں دا تزکیۂ نفس تے تصفیۂ قلب فرمیندے ہن۔ (حقائق عن التصوف)", "bait.009": "ساݙے ݙاݙا مرشد شمس الکونین فاتحِ قادیانیت خواجہ محمد عبدالخالقؒ فرمیندے ہن: بیعت لفظ بیع توں نکلیا ہے جیندا معنیٰ وِکݨ ہے۔ جیں ویلے مرید بیعت تھیندا ہے تاں آپݨے سارے ارادے پیر دے سپرد کر ݙیندا ہے۔ جیہڑی شے ویچ ݙتی ونڄے اوہ ݙوہاں دی رضامندی توں بغیر واپس نئیں گھدی ونڄ سڳدی۔ تاں اونکوں ٻئی جاہ کیویں ویچ سڳدا ہے۔ (لمعاتِ کمالاتِ قادریہ)", "bait.010": "بیعتِ طریقت دا مقصد", "bait.011": "امامِ ربانی مجدد الفِ ثانیؒ فرمیندے ہن جو شریعت دے ترے جز علم، عمل تے اخلاص ہن۔ تے طریقت شریعت دے تریجھے جز یعنی اخلاص حاصل کرݨ دا ذریعہ ہے۔ ایں سانگے طریقت، شریعت توں کوئی وکھری شے نئیں بلکہ شریعت کوں کامل کرݨ وچ شریعت دی خادم ہے۔", "bait.012": "ایں سانگے بیعت دا اصل مقصد اخلاص یعنی اللہ دی رضا دا حصول ہے۔ جیندا ذریعہ احکامِ شریعہ تے سنتِ نبوی ﷺ تے پوری طرحاں ٹُرݨ، خدا تعالیٰ دی مرضی تے راضی رہݨ، لالچ نہ کرݨ، عبادت وچ دل حاضر رکھݨ، دین دے کم اخلاص نال کرݨ، کہیں کوں حقیر نہ سمجھݨ، خود پسندی نہ ہووݨ، کاوڑ کوں ضبط کرݨ تے ذکر و فکر وچ لڳے رہݨ ہے۔ ایجھے اخلاق اختیار کرݨ کوں سلوک آہدے ہن۔", "bait.013": "ڄاݨݨا چاہیدا ہے جو ایں وچ نہ کشف تے کرامات ضروری ہن، نہ دنیاوی کماں وچ کامیابی دا وعدہ ہے، نہ جھاڑ پھونک نال بیماری دور تھیوݨ دا دعویٰ، نہ اڳوں پیش آوݨ والے واقعیاں دی خبر، نہ ای تصرفات لازم ہن جو پیر دی توجہ نال مرید دی اصلاح آپوں آپ تھی ویسی، نہ ایجھیاں باطنی کیفیتاں پیدا تھیوݨ دی کوئی میعاد ہے جو ہر ویلے یا گھٹ توں گھٹ عبادت ویلے لذت نال سرشار تے مست رہوے تے عبادت وچ خیال ای نہ آون، نہ ذکر و شغل وچ انوار وغیرہ دا نظر آوݨ یا کہیں آواز دا سݨیچݨ ضروری ہے، نہ ای چنڳے خواباں دا نظر آوݨ یا الہامات دا صحیح تے درست ہووݨ ضروری ہے۔", "bait.014": "شیخِ کامل دیاں شرطاں", "bait.015": "اڄ کل جعلسازی تے شعبدہ بازی عروج تے ہے تے تصوف دے اصل چہرے کوں بگاڑ تے پیش کیتا ویندا پیا ہے۔ ایں سانگے ضمنی طور تے شیخِ کامل دیاں پنج شرطاں بیان کیتیاں ویندیاں ہن تاں جو سالکانِ طریقت اصل تے نقل دی پچھاݨ آپ کر تے آپݨے آپ کوں گمراہی توں بچا سڳن۔", "bait.016": "اعلیٰ حضرت امام احمد رضا خان بریلویؒ پیرِ کامل دیاں شرطاں دے حوالے نال فرمیندے ہن جو", "bait.017": "<b class=\"az-n\">۱۔ عقیدہ:</b> پیر مذہبِ اہلِ سنّت والجماعت دا صحیح العقیدہ ہووے کیوں جو بد مذہب گمراہ دا سلسلہ شیطان تئیں پہنچسی نہ جو رسول اللہ ﷺ تئیں۔ (اڄ کل جے کہیں پیر دا عقیدہ حضرات شیخین یعنی حضراتِ صدیق و عمر رضی اللہ عنہما دی افضلیت دے خلاف ہووے یا سیدنا امیر معاویہؓ بارے چنڳی رائے نہ رکھدا ہووے تاں سُنّی مرید کوں چاہیدا ہے جو ایجھے پیر دی بیعت فوراً توڑ تے کہیں صحیح العقیدہ شیخ کولوں بیعت کر گھنے)۔", "bait.018": "عقیدے دی درستگی بارے قیومِ زماں مرزا مظہر جانِ جاناں شہیدؒ دہلوی فرمیندے ہن: اہلِ بیتِ اطہار نال محبت دا اظہار تے صحابہ کرامؓ دی ہکو جہی تعظیم لازم ہے۔ ایہو صراطِ مستقیم ہے جیہڑا قیامت دے ݙینہہ پُل صراط دی صورت وچ ظاہر تھیسی، جیہڑا دنیا وچ ایں راہ توں نئیں پھریا اوہ قیامت دے ݙینہہ ایں توں استقامت نال لنگھ ویسی۔ (مقاماتِ مظہری)", "bait.019": "<b class=\"az-n\">۲۔ علم:</b> اتنا علم شرط ہے جو کہیں مدد توں بغیر آپݨی لوڑ دے مسئلے کتاب وچوں کڈھ سڳے۔ مطالعہ کر تے تے لوکاں کولوں سُݨ سُݨ تے وی عالم بݨ سڳدا ہے۔ فارغ التحصیل ہووݨ دی سند نہ شرط ہے نہ کافی، بلکہ علم ہووݨا چاہیدا ہے۔ احکامِ شریعت امر و نہی، حلال و حرام، فرض و واجب، سنّت و مستحب تے کفر و اسلام یعنی علمِ فقہ توں باخبر ہووے۔ تے عربی عبارت چنڳی طرحاں پڑھ سڳدا ہووے۔", "bait.020": "ساݙے ݙاݙا مرشد شمس الکونین خواجہ محمد عبدالخالق شمس العرفانی نقشبندیؒ فرمیندے ہن", "bait.021": "<b class=\"az-n\">۳۔ عمل:</b> آپݨے علم تے عمل کرݨ والا ہووے۔ کوئی فرض، سنت یا مستحب اوں توں قضا نہ تھیوے اتھوں تئیں جو کنگھی تے مسواک ورتیندا ہووے، نماز باجماعت پڑھے تے جمعہ نہ چھوڑے۔ شریعت تے پکے طریقے نال عمل کرے تے متابعتِ مصطفیٰ ﷺ وچ کوتاہی نہ کرے۔", "bait.022": "<b class=\"az-n\">۴۔ اخلاص:</b> شمس الکونین خواجہ عبدالخالقؒ فرمیندے ہن جو پیر دا ہر عمل اللہ دی رضا کیتے ہووے۔", "bait.023": "<b class=\"az-n\">۵۔ سلسلہ تے خلافت:</b> پیر دا سلسلۂ طریقت صحیح ہووے یعنی اوہ کہیں پیر دا مرید ہووے تے خلافت یافتہ ہووے تاں جو اوندا ہتھ دست بدست رسول اللہ ﷺ تئیں پہنچے۔ جیہڑا بندہ خلافت توں بغیر بیعت کریندا ہے، اہلِ طریقت اونکوں زندیق سمجھدے ہن تے اوہ گمراہ ہے۔ تے کجھ لوک مرید تھئے بغیر صرف پیر زادے ہووݨ دے گمان وچ آپݨے پیو ݙاݙے دے مزار تے سجادہ نشین بݨ تے ٻہہ ویندے ہن۔ یا سلسلہ ای اوہ ہووے جیہڑا کٹ ݙتا ڳیا ہووے، ایں وچ فیض نہ رکھیا ڳیا ہووے تے لوک ہوس پاروں ایں سلسلے وچ خلافت ݙیندے آندے ہوون، یا سلسلہ تاں صحیح ہا پر وچکار کوئی ایجھا بندہ آ ڳیا جیہڑا پیری دے لائق نہ ہا، اوں توں جیہڑی شاخ ٹری اوہ وچکاروں کٹی ہوئی ہے۔ اِنہاں ساریاں صورتاں وچ ایجھی بیعت نال ہرگز دستِ رسول اللہ ﷺ تئیں نہ پہنچسی تے فیض حاصل نہ تھیسی کیوں جو ڈھڳے توں دُدھ یا بانجھ توں ٻال نئیں تھیندا۔", "bait.024": "شیخِ کامل دیاں بنیادی صفتاں", "bait.025": "ڄاݨݨا چاہیدا ہے جو پیرِ کامل وچ ہیٹھ ݙتیاں پنج صفتاں ضرور ہووݨیاں چاہیدیاں ہن۔", "bait.026": "سلطان العارفین شیخ بایزیدؒ بسطامی فرمیندے ہن:", "bait.027": "<b class=\"az-n\">۱۔</b> پیر خوش اخلاق ہووے۔", "bait.028": "<b class=\"az-n\">۲۔</b> سخی ہووے۔", "bait.029": "<b class=\"az-n\">۳۔</b> عاجز ہووے۔", "bait.030": "ساݙے شمس الکونین خواجہ عبدالخالقؒ فرمیندے ہن:", "bait.031": "<b class=\"az-n\">۴۔</b> پیر خلقِ عظیم رکھدا ہووے تاں جو مرید دیاں مشکلاں سوکھیاں حل تھیون۔", "bait.032": "<b class=\"az-n\">۵۔</b> پیر بیعت کریندے ویلے ہر موئے تن توں ذکر اسمِ ذات جاری کرا ݙیوے۔", "mamulat.001": "ختمِ خواجگانِ نقشبندیہ", "mamulat.002": "جاری کردہ مظہرِ جمالِ مصطفائی خواجۂ خواجگان، حامئ بیوگان، دستگیرِ یتامیٰ، فاتحِ قادیانیت، قطب الاقطاب، شمس الکونین ابوسعد محمد عبدالخالق نقشبندیؒ", "mamulat.003": "نوٹ: ہر ورد توں پہلے ہک واری بسم اللہ شریف ضرور پڑھو۔", "mamulat.004": "(میں اللہ کولوں بخشش منگدا ہاں جیندے سوا کوئی معبود کائنی، اوہ زندہ تے قائم رکھݨ والا ہے تے میں اوندی طرف رجوع کریندا ہاں)۔", "mamulat.005": "سورۃ الفاتحہ <span class=\"kk-c\">۷ واری</span>", "mamulat.006": "درودِ خالقیہ", "mamulat.007": "(اے اللہ! آپݨی کل معلومات دے برابر درود بھیڄ ساݙے سردار حضرت محمد ﷺ تے تے ساݙے سردار حضرت محمد ﷺ دی آل تے اصحاب تے)۔", "mamulat.008": "سورۃ الم نشرح <span class=\"kk-c\">۷۹ واری</span>", "mamulat.009": "سورۃ الاخلاص بسم اللہ شریف سمیت <span class=\"kk-c\">۱۰۰۰ واری</span>", "mamulat.010": "سورۃ الفاتحہ <span class=\"kk-c\">۷ واری</span>", "mamulat.011": "ہیٹھ ݙتے سارے کلمات سو سو واری پڑھو:", "mamulat.012": "درودِ خالقیہ", "mamulat.013": "(ڳناہاں توں بچݨ دی طاقت تے نیکی کرݨ دی قوت اللہ دی طرفوں ہے)", "mamulat.014": "(تیݙے سوا کوئی معبود کائنی، توں پاک ہیں (ظلم کرݨ توں)، بے شک میں ای ظالماں وچوں ہاں، یعنی آپݨے اُتے ظلم کر ٻہندا ہاں)۔", "mamulat.015": "(یاحی و قیوم آپݨی رحمت دے صدقے مدد فرما، اے مدد منگݨ والیاں دے مددگار)", "mamulat.016": "(اے عزت والے! میکوں مخلوق دی نظر وچ عزت دار بݨا)", "mamulat.017": "(اے حاجتاں پوریاں کرݨ والے)", "mamulat.018": "(اے درجات بلند کرݨ والے)", "mamulat.019": "(اے بلاواں کوں دور کرݨ والے)", "mamulat.020": "(اے مشکلاں کوں کھولݨ والے)", "mamulat.021": "(اے بیماریاں توں شفاء ݙیوݨ والے)", "mamulat.022": "(اے دعاواں قبول کرݨ والے)", "mamulat.023": "(اے مشکلاں حل کرݨ والے)", "mamulat.024": "(اے سبب پیدا کرݨ والے)", "mamulat.025": "(اے بے نیاز تے غنی بݨا ݙیوݨ والے)", "mamulat.026": "(اے ہر شے توں بے نیاز تے بے پرواہ)", "mamulat.027": "(اے کثرت نال پیدا کرݨ والے)", "mamulat.028": "(اے رزق ݙیوݨ والے تے ٻہوں عطا کرݨ والے)", "mamulat.029": "(اے انعام تے نعمتاں عطا کرݨ والے)", "mamulat.030": "(اے بے نیاز! ٻئے ساریاں توں بے نیاز کر ݙیوݨ والے)", "mamulat.031": "(اے بے حد محبت کرݨ والے)", "mamulat.032": "(اے ہر ہک تے بے حد رحم کرݨ والے)", "mamulat.033": "(اے آپݨے خاص تے چاہݨ والیاں تے ٻہوں ای مہربان)", "mamulat.034": "(اے ٻہوں کرم کرݨ والے)", "mamulat.035": "(اے بخشݨ والے)", "mamulat.036": "(اے ٻہوں ای درگزر تے پردہ پوشی کرݨ والے)", "mamulat.037": "(اے مشکل کشا تے آسانیاں دا دروازہ کھولݨ والے)", "mamulat.038": "(اے سب کجھ عطا کرݨ والے)", "mamulat.039": "(اے عزت ݙیوݨ والے)", "mamulat.040": "(اے بلندی عطا کرݨ والے)", "mamulat.041": "(اے روزی کشادہ کرݨ والے)", "mamulat.042": "(اے بے عیب ذات! سلامتی عطا کرݨ والے)", "mamulat.043": "(اے حقیقی کارساز)", "mamulat.044": "(اے نگہبان! مخلوق دی نگہبانی کرݨ والے)", "mamulat.045": "(اے سارے جہاناں دے پروردگار)", "mamulat.046": "(اے سارے جہاناں دے حقیقی پالݨ والے)", "mamulat.047": "(اے سارے جہاناں دے حقیقی ربّ)", "mamulat.048": "(آپݨی رحمت دے صدقے! اے سب توں ودھ رحم کرݨ والے)", "mamulat.049": "ہݨ نکا ختم شریف پڑھو:", "mamulat.050": "(اے اللہ! میں تیݙے کولوں مغفرت منگدا ہاں)", "mamulat.051": "(اے اللہ! اے میݙے ربّ! میں ہر ڳناہ توں معافی منگدا ہاں تے تیݙی طرف رجوع کریندا ہاں)", "mamulat.052": "سورۃ الفاتحہ <span class=\"kk-c\">۷ واری</span>", "mamulat.053": "درودِ خالقیہ <span class=\"kk-c\">۱۱ واری</span>", "mamulat.054": "بطفیل حضور نبی کریم ﷺ، سارے انبیاء کرام علیہم السلام، خلفائے راشدین، اہلِ بیت اطہار، صحابہ کرام رضی اللہ عنہم تے پیرانِ عظام کوں ایصالِ ثواب کرو۔", "shajra.001": "شجرۂ طریقت", "shajra.002": "چاراں سلسلیاں توں خلافت دے باوجود ساݙے مرشدین سلسلہ عالیہ نقشبندیہ مجددیہ دی ترویج کیتی۔ ایں سانگے سلسلہ عالیہ دے بزرگاں دے ناں عام لوکاں دی آگاہی کیتے تبرک دے طور تے پیش کیتے ویندے پئے ہن۔", "shajra.003": "رحمۃ للعالمین، خاتم النبیین، سید المرسلین، حضرت محمد مصطفیٰ ﷺ<small>وصال 11ھ ۔ مدفن گنبدِ خضریٰ</small>", "shajra.004": "یارِ غار و مزار، افضل البشر بعد الانبیاء بالتحقیق، سیدنا ابوبکر صدیقؓ<small>13ھ ۔ گنبدِ خضریٰ، مدینہ منورہ</small>", "shajra.005": "صحابیِ پاکباز، صاحبِ رسول اللہ ﷺ، حضرت سیدنا سلمان فارسیؓ<small>33ھ ۔ مدائن، عراق</small>", "shajra.006": "حضرت سیدنا امام قاسمؒ بن سیدنا محمدؒ بن سیدنا ابوبکر صدیقؓ<small>106ھ ۔ مدینہ منورہ</small>", "shajra.007": "امام الشریعت، ہادیِ طریقت حضرت سیدنا امام جعفر صادقؒ<small>148ھ ۔ جنت البقیع، قبۂ اہلِ بیت</small>", "shajra.008": "سلطان العارفین، غوثِ زمانی، حضرت شیخ بایزید بسطامیؒ<small>261ھ ۔ بسطام، ایران</small>", "shajra.009": "قطبِ ربانی، غوثِ زماں، خواجہ ابوالحسن خرقانیؒ<small>425ھ ۔ بسطام دے نیڑے خرقان، ایران</small>", "shajra.010": "عارفِ ربانی، قطبِ زمانی، حضرت شیخ ابوالقاسم گرگانیؒ<small>450ھ ۔ گرگان، ایران</small>", "shajra.011": "قطبِ صمدانی، حضرت شیخ بوعلی فارمدیؒ<small>477ھ ۔ طوس دے نیڑے فارمد، خراسان، ایران</small>", "shajra.012": "رئیس الطریقت، غوثِ زماں، امامِ ربانی، خواجہ یوسف ہمدانیؒ<small>535ھ ۔ مرو، ایران</small>", "shajra.013": "امام الطریقت خواجۂ جہاں خواجہ عبدالخالق غجدوانیؒ<small>575ھ ۔ بخارا دے نیڑے غجدوان، ازبکستان</small>", "shajra.014": "نورِ خدا، واقفِ معارفِ پیغمبری، خواجہ عارف ریوگریؒ<small>616ھ ۔ بخارا دے نیڑے ریوگر، ازبکستان</small>", "shajra.015": "خواجۂ خواجگاں، قطبِ جہاں، حضرت خواجہ محمود انجیر فغنویؒ<small>715ھ ۔ بخارا دے نیڑے انجیر فغنہ</small>", "shajra.016": "قطبِ زماں، مجددِ دوراں، حضرت خواجہ عزیزان علی رامیتنیؒ<small>718ھ ۔ خوارزم، ازبکستان</small>", "shajra.017": "بابِ الطریقت، آفتابِ حقیقت حضرت خواجہ بابا محمد سماسیؒ<small>755ھ ۔ بخارا دے نیڑے سماس</small>", "shajra.018": "عارفِ باکمال، صاحبِ وجد و حال، شمس الدین سید امیر کلالؒ<small>772ھ ۔ سوخار، بخارا</small>", "shajra.019": "امام الطریقت پیرِ پیراں خواجۂ خواجگاں خواجہ بہاؤالدین نقشبندؒ<small>791ھ ۔ قصرِ عارفاں، بخارا</small>", "shajra.020": "امام العارفین، قطبِ ارشاد حضرت خواجہ علاؤالدین عطارؒ<small>802ھ ۔ بخارا دے نیڑے چغانیاں</small>", "shajra.021": "شمس الہدایت، عارفِ ربانی، حضرت مولانا محمد یعقوب چرخیؒ<small>851ھ ۔ ماوراء النہر، تاجکستان</small>", "shajra.022": "مرشدِ عارف، خواجہ ناصرالدین عبیداللہ احرارؒ<small>895ھ ۔ سمرقند، ازبکستان</small>", "shajra.023": "فیضِ الٰہی، یکتائے زمانہ، حضرت مولانا خواجہ محمد زاہد وخشیؒ<small>936ھ ۔ وخش، بلخ</small>", "shajra.024": "مستِ عشق، حضرت مولانا خواجہ درویش محمد امکنگیؒ<small>970ھ ۔ ماوراء النہر</small>", "shajra.025": "مرکزِ دائرۂ قطبیت، دربانِ رسول مولانا شاہ محمد خواجگی امکنگیؒ<small>1008ھ ۔ امکنہ، بخارا</small>", "shajra.026": "فخرِ اسلام، نقشبندِ وقت، قطبِ زماں، خواجہ محمد باقی باللہ بیرنگؒ<small>1012ھ ۔ دہلی، انڈیا</small>", "shajra.027": "قیومِ اوّل، امامِ ربانی، مجدد الفِ ثانی، شیخ احمد فاروقی سرہندیؒ<small>1034ھ ۔ سرہند، انڈیا</small>", "shajra.028": "قیومِ ثانی، عروۃ الوثقیٰ خواجہ محمد معصومؒ<small>شہزادۂ مجدد الفِ ثانیؒ ۔ 1079ھ ۔ سرہند شریف</small>", "shajra.029": "قاطعِ بدعت، محتسبِ اُمت شیخ سیف الدینؒ<small>شہزادۂ قیومِ ثانیؒ ۔ 1096ھ ۔ سرہند شریف</small>", "shajra.030": "کشف الدجیٰ حضرت حافظ محمد محسنؒ<small>خلیفہ خواجہ محمد معصومؒ ۔ 1147ھ ۔ دہلی</small>", "shajra.031": "حضرت سید نور محمد بدایونیؒ<small>خلیفہ شیخ سیف الدینؒ ۔ 1135ھ ۔ دہلی</small>", "shajra.032": "قطبِ زماں خواجہ محمد عابد سنامیؒ<small>خلیفہ عبدالاحد سرہندی مجددی قادریؒ ۔ 1160ھ ۔ دہلی</small>", "shajra.033": "قیومِ زماں، قطبِ جہاں، شمس الدین حبیب اللہ مرزا مظہر جانِ جاناں شہیدؒ<small>1195ھ ۔ دہلی</small>", "shajra.034": "مجددِ دوراں، قیومِ زماں حضرت شاہ عبداللہ غلام علی دہلویؒ<small>1240ھ ۔ دہلی</small>", "shajra.035": "شیخ المشائخ، قیومِ زماں، حضرت شاہ ابوسعید فاروقی مجددیؒ<small>1250ھ ۔ دہلی</small>", "shajra.036": "شمس الاولیاء، حضرت مولانا بابا محمد شریف قندھاریؒ<small>1260ھ ۔ سرہند شریف</small>", "shajra.037": "سلطان الفقراء، حضرت حاجی محمود جالندھریؒ<small>1306ھ ۔ جالندھر شریف، انڈیا</small>", "shajra.038": "شمس العرفان خواجہ قادر بخشؒ<small>1306ھ ۔ کوٹ عبدالخالق جہانخیل، ضلع ہوشیارپور، انڈیا</small>", "shajra.039": "شمس الکونین خواجہ محمد عبدالخالق نقشبندیؒ<small>1931ء ۔ کوٹ عبدالخالق جہانخیل، ضلع ہوشیارپور، انڈیا</small>", "shajra.040": "شمس العارفین سائیں عبدالرزاق خالقی نقشبندیؒ<small>1982ء ۔ دیپالپور شریف، ضلع اوکاڑہ</small>", "shajra.041": "امام الذاکرین حضور سائیں محمد عظیم اللہ رزاقی نقشبندیؒ<small>2013ء ۔ عظیم نگر شریف، ضلع بہاولنگر</small>", "shajra.042": "شجرہ شریف (منظوم)", "shajra.043": "ایں شجرہ طیبہ کوں ٻہوں ادب نال باوضو پڑھݨ دی سخت تاکید ہے۔ پڑھدیاں ویلے دل حاضر کر تے آپݨے سبق دی طرف دھیان لاؤ، آپݨی روحانی نسبت درست رکھ تے پیرانِ عظام کولوں فیض منگو۔ ایہ شجرہ طیبہ حضور سید عالم محمد مصطفیٰ ﷺ دا محبوب تے مقبول ہے۔ نبی کریم رؤف رحیم ﷺ آپݨے ایں غلاماں دے غلام دی عاجزی کوں قبول فرما تے خواب وچ فقیر کوں آگاہ فرمایا ہے جو جیہڑا بندہ ایں شجرہ طیبہ کوں خلوصِ نیت نال پڑھسی، اوندی کیجھی وی مشکل ہووے، ان شاء اللہ العزیز بہ طفیلِ خواجگانِ نقشبندیہ ضرور حل تھیسی۔ شجرہ شریف پڑھ تے حضور نبی کریم ﷺ دے وسیلے نال عرض گزارو تے محلل المشکلات، مسبب الاسباب، الٰہ العالمین کولوں مشکلاں دے حل کیتے دعا منگو۔", "shajra.044": "محمد مصطفیٰ ﷺ دے واسطے میݙی دستگیری کر", "shajra.045": "آل تے اصحاب تے سارے انبیاء دے واسطے", "shajra.046": "یا الٰہی، آپݨا درد میݙے دل دا نصیب بݨا", "shajra.047": "صاف دل بوبکر صدیقِ اکبرؓ دے واسطے", "shajra.048": "اے خداوند، آپݨے عشق وچ میکوں کباب بݨا", "shajra.049": "حیا والے صاحب سلمانؓ فارس دے واسطے", "shajra.050": "اللہ دے سوا میݙے دل توں سارے خیال دور تھی ونڄن", "shajra.051": "ہدایت دے پیر امام قاسمؒ دے واسطے", "shajra.052": "یا الٰہی، کافر نفس دے شر توں بچا گھن", "shajra.053": "پرہیزگاراں دے امام جعفر صادقؒ دے واسطے", "shajra.054": "یا الٰہی، میکوں شیطان دے مکر توں آگاہ کر", "shajra.055": "رہنما صاحب بایزیدؒ دے واسطے", "shajra.056": "میں ہک ساہ وی تیݙی یاد توں غافل نہ تھیواں", "shajra.057": "اولیاء دے تاج خواجۂ بوالحسنؒ دے واسطے", "shajra.058": "اے رب، میکوں آپݨی ذاتِ مطلق وچ فنا کر", "shajra.059": "جھنڈے والے اوں شاہ بوالقاسمؒ دے واسطے", "shajra.060": "اے میݙے رب، میکوں عینِ مطلق ذات توں وکھرا نہ کر", "shajra.061": "وفادار پیر تے مرشد بو علیؒ دے واسطے", "shajra.062": "دل توں غیر دی غیریت کڈھ ݙے تے ہمیشہ دی حضوری عطا کر", "shajra.063": "مقبول الدعا شاہ خواجہ یوسفؒ دے واسطے", "shajra.064": "اے رب، میݙی روح نقل توں نکل تے اصل نال شامل تھی ونڄے", "shajra.065": "خطاواں دی شفاعت کرݨ والے عبدِ خالقؒ غجدوانی دے واسطے", "shajra.066": "نفس دی معرفت ݙے تاں جو میں اصل کوں سُنڄاݨ گھناں", "shajra.067": "نورِ خدا محمد عارفؒ دے واسطے", "shajra.068": "عاشقاں دے دائرے کوں معشوق نال ملا ݙے", "shajra.069": "انجیر فغنہ والے خواجۂ محمودؒ دے واسطے", "shajra.070": "ایہ غریب ہر دم تیݙے وصل وچ آرام کرے", "shajra.071": "شاہ عزیزانؒ علیِ مرتضیٰ دے واسطے", "shajra.072": "آپݨی رحمت دی نظر نال میݙیاں ساریاں خطاواں معاف کر", "shajra.073": "ادب والے خواجۂ بابا محمدؒ دے واسطے", "shajra.074": "یا الٰہی! میکوں اُمتِ احمد ﷺ وچ شمار کر گھن", "shajra.075": "رضا والے سیّد میر کلالؒ دے واسطے", "shajra.076": "میکوں شریعت تے طریقت تے ثابت قدم رکھ", "shajra.077": "پیشوا شاہ بہاؤالدینؒ خواجہ دے واسطے", "shajra.078": "صراطِ مستقیم تے ہمیشہ دی استقامت عطا کر", "shajra.079": "نور والے شاہ علاؤالدین عطارؒ دے واسطے", "shajra.080": "اے خداوند، میکوں پیر دی محبت عطا کر", "shajra.081": "بے ریا خواجۂ یعقوبؒ چرخی دے واسطے", "shajra.082": "اے رب، میکوں پیرانِ کرام دی نظر وچ مقبول بݨا", "shajra.083": "سخاوت والے عبیداللہؒ احرار دے واسطے", "shajra.084": "میݙے پیر دا عشق میݙے دل وچ وسا ݙے", "shajra.085": "برگزیدہ خواجۂ زاہد محمدؒ دے واسطے", "shajra.086": "اے رب، پیراں دی نصیحت دا ہر دم میکوں خیال رہوے", "shajra.087": "دلربا خواجۂ درویش محمدؒ دے واسطے", "shajra.088": "اے کریم خداوند، میݙے دل وچ توکل عطا کر", "shajra.089": "بلند شان والے شاہ محمدؒ خواجگی دے واسطے", "shajra.090": "میکوں دنیا وچ کݙاہیں غمگین نہ کریں", "shajra.091": "بقا والے محمد باقیؒ باللہ دے واسطے", "shajra.092": "اے میݙے الٰہ، آپݨے سوا کہیں غیر دا محتاج نہ کر", "shajra.093": "اندھاریاں دے چودھویں چن مجددؒ صاحبؒ دے واسطے", "shajra.094": "جݙاں نزع دا ویلا ہووے، تیݙا کلمہ زبان تے ہووے", "shajra.095": "حضرتِ معصوم خواجہؒ دے واسطے، اے کبریا", "shajra.096": "اوں ویلے میکوں شیطان دے شر توں بچا گھنیں", "shajra.097": "مصطفیٰ ﷺ دے عاشق شیخ سیف الدینؒ دے واسطے", "shajra.098": "آپݨے فضل نال میکوں سکرات وچ چھٹکارا ݙیویں", "shajra.099": "مخلوق دی پناہ محمد عابدؒ دے واسطے", "shajra.100": "الٰہی، تیݙے فضل نال میݙی قبر روشن تھیوے", "shajra.101": "اندھارے دور کرݨ والے شہ محمد محسنؒ دے واسطے", "shajra.102": "نہ قبر دی سختی ہووے تے نہ فرشتے دی پچھ وچ کوئی خلل", "shajra.103": "سوہݨے چہرے والے سید نور محمدؒ دے واسطے", "shajra.104": "جیں ویلے پل صراط تے ٹُراں، لنگھݨ سوکھا ہووے", "shajra.105": "ساݙی جان خواجہ مرزا جانِ جاناںؒ دے واسطے", "shajra.106": "اے رب، جیں ویلے تیݙا سجھ تیز ہووے، امن عطا کر", "shajra.107": "چاشت دے سجھ غلام شاہ علیؒ دے واسطے", "shajra.108": "یا الٰہی، میزان وچ نیکی دا پلڑا بھارا ہووے", "shajra.109": "برگزیدہ لوکاں دے رہنما بو سعیدؒ دے واسطے", "shajra.110": "اے جہان دے پیدا کرݨ والے، اوں ویلے کوئی خلل نہ ہووے", "shajra.111": "جان قربان کرݨ والے محمد شریفؒ دے واسطے", "shajra.112": "اے علیم خداوند، میݙا شمار عاشقاں وچ ہووے", "shajra.113": "دل کھولݨ والے حاجیِ محمود حافظؒ دے واسطے", "shajra.114": "اے رب، قیامت دے ݙینہہ میں پیر دے سائے ہیٹھ رہواں", "shajra.115": "ہما دے سائے ورگے خواجہ قادر بخشؒ دے واسطے", "shajra.116": "جدائی دے تاپ نال دل وچ درد ہے، ایندی دوا کر ݙے", "shajra.117": "سڑے ہوئے دل دی دوا شمسِ عرفاںؒ دے واسطے", "shajra.118": "اے رب، محبوب دا وصل ہر دم میݙا نصیب رہوے", "shajra.119": "بلند تعریف والے ساریاں خواجگاں دے خواجہؒ دے واسطے", "shajra.120": "میں غریب حال ہاں، اے رب رحم دی نظر کر", "shajra.121": "شانِ مصطفیٰ ﷺ والے محبوب مرشد دے واسطے", "shajra.122": "یعنی میݙی جان دے قبلہ، جہان دی پناہ خواجہ", "shajra.123": "پیشوا شمس الکونین عبدالخالقؒ دے واسطے", "shajra.124": "اے میݙے الٰہ، میکوں دین تے دنیا وچ سرخرو کر", "shajra.125": "میݙے پیارے پیشوا سائیںؒ خواجہ دے واسطے", "shajra.126": "غوثِ دوراں، قطبِ عالم، روشن ضمیر مرشد", "shajra.127": "اولیاء دے امام سائیں عبدالرزاقؒ دے واسطے", "shajra.128": "اے میݙے کریم رب، امید دا دامن بھر ݙے", "shajra.129": "ظلِ الٰہ دی صورت والے پیرِ کامل دے واسطے", "shajra.130": "میݙے دل تے نظر کوں ایمان دے نور نال سجا ݙے", "shajra.131": "نورِ خدا شہ محمد عظیم اللہؒ دے واسطے", "shajra.132": "تیݙے سوا کوݨ ہے، میں دل دا درد کیں کوں ݙساں", "shajra.133": "ہر مراد کیتے توں ای حاجت روا ہیں", "shajra.134": "اے خدا، سینکڑاں اوکھائیاں دا سامݨا ہے", "shajra.135": "آپݨی کبریائی دی شان دے واسطے سوکھا کر ݙے", "shajra.136": "بھانویں بُرا ہاں پر تیݙا ہاں، اے میݙے عزّ و جل", "shajra.137": "میں بے نوا کیتے تیݙی رحمت چاہیدی ہے", "shajra.138": "یا الٰہی، میݙی اولاد کوں نصیب والا بݨا", "shajra.139": "انبیاء تے اولیاء دی سخاوت تے عطا دے واسطے", "shajra.140": "دوستاں تے سڳے سنبندھیاں کوں محبت عطا کر", "shajra.141": "پیشوا نبی ﷺ دی آل تے حرمین دے واسطے", "shajra.142": "یا الٰہی، آپݨے ڳناہگار دی دعا قبول کر گھن", "shajra.143": "قیامت دے ݙینہہ شفاعت کرݨ والے جناب ﷺ دے واسطے", "azkar.001": "اذکارِ مسنونہ", "azkar.002": "نمازِ فجر تے مغرب توں بعد دے مسنون اذکار", "azkar.003": "<p class=\"kk-ar\" lang=\"ar\">وَسَبِّحُوْهُ بُكْرَةً وَّاَصِيْلًا</p><p class=\"kk-ur\">تے صبح شام اوندی تسبیح کیتا کرو۔ (سورۃ احزاب: ۴۲)</p>", "azkar.004": "نوٹ: ساݙے امام ربانی مجدد الفِ ثانیؒ ہمیشہ صبح شام دے مسنون اذکار پڑھیا کریندے ہن۔", "azkar.005": "(اللہ تعالیٰ دے سوا کوئی معبود کائنی، اوہ کلہا ہے، اوندا کوئی شریک کائنی، اوندی بادشاہی ہے تے اوندی تعریف ہے تے اوہ ہر شے تے قادر ہے)۔", "azkar.006": "اے اللہ! میکوں جہنم توں نجات عطا فرما۔", "azkar.007": "میکوں اللہ کافی ہے، اوندے سوا کوئی معبود کائنی، میں اوندے اُتے بھروسہ کیتا تے اوہ عرشِ عظیم دا رب ہے۔", "azkar.008": "میں اوں ذات تے بھروسہ رکھدا ہاں جیہڑی زندہ ہے، جینکوں موت کائنی۔", "azkar.009": "(صحیح مسلم)", "azkar.010": "۶۔ سورۃ الاخلاص تے معوذتین تسمیہ سمیت <span class=\"kk-c\">۳ واری</span>", "azkar.011": "(ابوداؤد)", "azkar.012": "میں اللہ تعالیٰ دے ربّ ہووݨ، اسلام دے دین ہووݨ تے ساݙے سردار حضرت محمد ﷺ دے نبی تے رسول ہووݨ تے راضی تھیا۔", "azkar.013": "(جامع ترمذی)", "azkar.014": "اللہ تعالیٰ دے ناں نال، جیندے ناں دی برکت نال زمین تے آسمان دی کوئی شے نقصان نئیں پُچا سڳدی تے اوہ سُݨݨ والا، ڄاݨݨ والا ہے۔", "azkar.015": "(ترمذی)", "azkar.016": "اے اللہ! میݙے بدن وچ عافیت ݙے، اے اللہ! میݙے سُݨݨ وچ عافیت ݙے، اے اللہ! میݙی ݙیکھݨ وچ عافیت ݙے، تیݙے سوا کوئی معبود کائنی۔", "azkar.017": "(صحیح مسلم)", "azkar.018": "میں اللہ دے پورے تے کامل کلمات دے نال مخلوق دے شر توں پناہ منگدا ہاں۔", "azkar.019": "(صحیح مسلم)", "azkar.020": "پنج ویلے نماز توں بعد دے مسنون اذکار", "azkar.021": "<p class=\"kk-ar\" lang=\"ar\">فَاِذَا قَضَيْتُمُ الصَّلٰوةَ فَاذْكُرُوا اللّٰهَ قِيٰمًا وَّقُعُوْدًا وَّعَلٰى جُنُوْبِكُمْ</p><p class=\"kk-ur\">وت جݙاں تساں نماز پڑھ گھنو تاں کھڑے، ٻیٹھے تے پاسیاں تے لیٹے اللہ دا ذکر کرو۔ (سورۃ النساء: ۱۰۳)</p>", "azkar.022": "<p class=\"kk-ar\" lang=\"ar\">فَسَبِّحْهُ وَاَدْبَارَ السُّجُوْدِ</p><p class=\"kk-ur\">تے اوندی تسبیح کرو تے نمازاں توں بعد وی۔ (سورۃ ق: ۴۰)</p>", "azkar.023": "نوٹ: ساݙے امام ربانی مجدد الفِ ثانیؒ ہر نماز توں بعد مسنون دعاواں پڑھدے ہن۔ کلمات پڑھدیاں ہویاں ترتیل، تجوید تے معنیاں دا خیال رکھو۔ ہر ورد توں پہلے تسمیہ پڑھو۔", "azkar.024": "اے اللہ! توں ای سلامتی والا ہیں تے تیݙی طرفوں ای سلامتی ہے۔ توں ٻہوں بابرکت ہیں، اے وݙی شان تے عزت والے۔", "azkar.025": "(صحیح مسلم)", "azkar.026": "۳۔ آیت الکرسی", "azkar.027": "(سلسلۃ الاحادیث الصحیحہ)", "azkar.028": "اے دلاں کوں پھیرݨ والے! میݙے دل کوں آپݨے دین تے آپݨی اطاعت تے قائم رکھ۔", "azkar.029": "(ترمذی)", "azkar.030": "اے ساݙے ربّ! ساݙے دل ونگے نہ کر ایں توں بعد جو توں سانکوں ہدایت ݙتی تے سانکوں آپݨے کولوں رحمت عطا کر، بے شک توں ٻہوں عطا کرݨ والا ہیں۔", "azkar.031": "(ابنِ ماجہ) (سورۃ آلِ عمران: ۸)", "azkar.032": "اے اللہ! آپݨے ذکر، شکر تے آپݨی بہترین عبادت کرݨ وچ میݙی مدد فرما۔", "azkar.033": "(ابوداؤد)", "azkar.034": "اے زندہ تے قائم رہݨ والے! تیݙے سوا کوئی معبود کائنی، میں سوال کریندا ہاں جو میݙے دل کوں ہمیشہ کیتے آپݨے نورِ معرفت نال زندہ رکھ، اے وݙے جلال تے بزرگی والے! توں پاک ہیں۔", "azkar.035": "(کنز العمال)", "azkar.036": "۸۔ تسبیحِ فاطمہ", "azkar.037": "سبحان اللہ ۳۳ واری، الحمد للہ ۳۳ واری، اللہ اکبر ۳۳ واری تے ہک واری کلمہ توحید۔", "azkar.038": "(صحیح مسلم)", "azkar.039": "(ترمذی)", "azkar.040": "۱۰۔ کلمہ تمجید", "azkar.041": "۱۱۔ تریہے قل شریف", "azkar.042": "۱۱۔ سورۃ اخلاص <span class=\"kk-c\">۱۰ واری</span>", "azkar.043": "(مسند احمد)", "azkar.044": "نکا ختمِ خواجگان", "azkar.045": "ہیٹھ ݙتا نکا ختمِ خواجگان نمازِ فجر تے نمازِ عصر توں بعد پڑھݨ دا معمول بݨاؤ۔", "azkar.046": "۱۔ اَستغفر اللہ <span class=\"kk-c\">۲۶ واری</span>", "azkar.047": "۲۔ سورۃ الفاتحہ <span class=\"kk-c\">۷ واری</span>", "azkar.048": "۳۔ درود شریف <span class=\"kk-c\">۱۱ واری</span>", "azkar.049": "نماز دیاں اضافی مسنون دعاواں", "azkar.050": "نوٹ: عروۃ الوثقیٰ خواجہ محمد معصوم سرہندیؒ فرمیندے ہن جو ثناء پڑھݨ توں علاوہ نماز شروع کرݨ دیاں ماثور دعاواں، تے ایویں تسبیحات توں علاوہ رکوع تے سجود دیاں دعاواں تے قومہ تے جلسہ دیاں دعاواں جیہڑیاں احادیثِ مبارکہ وچ آئیاں ہن، اُنہاں کوں تہجد تے ٻئے نفلاں وچ پڑھو تاں ایہ ٻہوں چنڳا ہے، تے چھیکڑی قعدے وچ درود شریف توں بعد قرآنی دعاواں یا ماثور تے مسنون دعاواں پڑھو۔ جیویں صحیح بخاری وچ حدیث شریف ہے: وت اوہ دعا منگے جیہڑی اونکوں پسند ہووے۔ (اذکارِ نبویہ)", "azkar.051": "اللہ سب توں وݙا ہے، ٻہوں وݙا، تے اللہ کیتے ٻہوں حمد ہے، تے صبح شام اللہ دی تسبیح کریندا ہاں۔ حضرت جبیر بن مطعمؓ بیان فرمیندے ہن جو اُنہاں نبی ﷺ کوں ہک نماز پڑھدیاں ݙٹھا، آپ ﷺ نماز دے شروع وچ ایہ کلمات پڑھے۔", "azkar.052": "(سنن ابوداؤد)", "azkar.053": "ٻہوں ای پاک، انتہائی مقدس، فرشتیاں تے روح دا ربّ۔ ایہ کلمات رکوع تے سجود وچ پڑھݨ سنت ہے۔ نبی ﷺ فرمایا: بندہ آپݨے ربّ دے سب توں ودھ نیڑے سجدے وچ ہوندا ہے، ایں سانگے سجدے وچ ودھ توں ودھ دعا کیتا کرو۔", "azkar.054": "(صحیح مسلم)", "azkar.055": "نوٹ: ساݙے امامِ ربانی مجدد الفِ ثانیؒ ویہلے ویلے رکوع تے سجود وچ پنج، ست، نو یا یارھاں واری تسبیحات پڑھدے ہن۔ تے فرمایا کریندے ہن جو شرم آندی ہے جو طاقت ہوندیاں ہویاں ویہلے ویلے وی صرف ترے تسبیحات تے ای بس کیتی ونڄے۔ (حضرات القدس)", "azkar.056": "اے میݙے ربّ! ساری تعریف تیݙے کیتے ہے، ایجھی تعریف جیہڑی ٻہوں زیادہ ہے، پاک ہے، برکت والی ہے۔ اے ساݙے ربّ! جیویں تیکوں پسند ہووے جیں نال توں راضی تھی ونڄیں۔ قومہ یعنی رکوع توں سر چاوݨ دے بعد ایہ کلمات خاص طور تے نفل نماز وچ پڑھݨ سنت ہے۔", "azkar.057": "(بخاری)", "azkar.058": "اے اللہ! میݙی بخشش فرما، میݙے اُتے رحم فرما، میکوں ہدایت ݙے، میکوں رزق ݙے، میکوں بلند درجہ عطا فرما، میݙی وڳڑی سنوار ݙے تے میکوں عافیت عطا فرما۔ ݙوہاں سجدیاں دے وچکار جلسے وچ خاص طور تے نفل نماز وچ اِنہاں کلمات کوں پڑھݨ سنت ہے۔", "azkar.059": "(سنن ابوداؤد، ترمذی)", "azkar.060": "آرام (سمݨ) ویلے دے مسنون اذکار", "azkar.061": "سورۃ الزمر وچ ارشادِ الٰہی ہے: اللہ تعالیٰ جاناں کوں اُنہاں دی موت ویلے وفات ݙیندا ہے تے اُنہاں جاناں کوں وی جنہاں دی موت نئیں آئی، اُنہاں دے سمݨ ویلے۔ (۴۲)", "azkar.062": "<p class=\"kk-ar\" lang=\"ar\">وَسَبِّحْهُ لَيْلًا طَوِيْلًا</p><p class=\"kk-ur\">سورۃ الدہر وچ ارشاد تھیا: تے لمی رات وچ اوندی تسبیح کرو۔ (۲۶)</p>", "azkar.063": "نبی کریم ﷺ فرمایا: دنیا وچ کجھ لوک نرم بستریاں تے اللہ تعالیٰ کوں یاد کریندے ہن، اللہ تعالیٰ اُنہاں کوں اعلیٰ جنّت وچ داخل فرمیسی۔ (مصنف ابی یوسف)۔ جیہڑا بندہ بستر تے لیٹے یا کہیں مجلس وچ ٻہوے تے اوں وچ اللہ تعالیٰ دا ذکر نہ کرے تاں قیامت دے ݙینہہ ایہ اوندے کیتے حسرت ہوسی۔ (ابوداؤد)", "azkar.064": "نوٹ: ساݙے امامِ ربانیؒ سمݨ ویلے سورتاں، آیات، تسبیحات تے ماثورہ دعاواں پڑھدے ہن۔", "azkar.065": "نبی کریم ﷺ سیدنا علی المرتضیٰؓ کوں فرمایا جو اے علیؓ! پنج کم کر تے سمیا کرو:", "azkar.066": "۱۔ سورۃ الفاتحہ <span class=\"kk-c\">۴ واری</span>", "azkar.067": "چار واری پڑھ تے سمیا کرو، ایہ چار ہزار دینار صدقہ کرݨ دے برابر ہے۔", "azkar.068": "۲۔ سورۃ اخلاص <span class=\"kk-c\">۳ واری</span>", "azkar.069": "ترے واری پڑھ تے سمیا کرو۔ ایہ ہک واری قرآن مجید پڑھݨ دے برابر ہے۔", "azkar.070": "ݙہ واری پڑھ تے سمیا کرو۔ ایندا اجر ݙو لڑݨ والیاں وچ صلح کراوݨ دے برابر ہے۔", "azkar.071": "۴۔ درود شریف <span class=\"kk-c\">۱۰ واری</span>", "azkar.072": "ݙہ واری پڑھ تے سمیا کرو۔ ایہ جنت دی قیمت ادا کرݨ دے برابر ہے۔", "azkar.073": "۵۔ کلمہ تمجید <span class=\"kk-c\">۴ واری</span>", "azkar.074": "چار واری پڑھ تے سمیا کرو۔ ایہ ہک حج کرݨ دے برابر ہے۔", "azkar.075": "۶۔ سورۃ الکافرون <span class=\"kk-c\">ہک واری</span>", "azkar.076": "حضرت نوفلؓ فرمیندے ہن جو نبی کریم ﷺ میکوں ارشاد فرمایا: سورۃ الکافرون پڑھ تے سمیا کرو کیوں جو ایہ شرک توں براءت ہے۔", "azkar.077": "(ابوداؤد)", "azkar.078": "۷۔ تریہے قل شریف <span class=\"kk-c\">۳ واری</span>", "azkar.079": "اُمّ المومنین عائشہ صدیقہؓ فرمیندیاں ہن جو جݙاں نبی کریم ﷺ آرام فرماوݨ کیتے بستر تے تشریف گھن آندے تاں ݙوہیں ہتھ جوڑ تے سورۃ اخلاص تے فلق تے ناس پڑھ تے دم کریندے تے بدنِ اقدس دے جیں حصے تئیں ہتھ پہنچدے اتھوں تئیں ہتھ پھریندے، تے ہتھ پھیرݨ دا شروع سر تے چہرے توں کریندے تے ایہ عمل ترے واری کریندے ہن۔", "azkar.080": "(صحیح بخاری)", "azkar.081": "نبی ﷺ فرمایا: جیہڑا بندہ ایہ اِستغفار بستر تے لیٹدیاں ویلے ترے واری پڑھ گھندا ہے اوندے ڳناہ بخش ݙتے ویندے ہن بھانویں سمندر دی جھاگ دے برابر ہوون، بھانویں رکھاں دے پتراں دے برابر ہوون، بھانویں ٹِبیاں دی ریت دے ذرّیاں دے برابر ہوون، بھانویں دنیا دے ݙینہاں دے برابر ہوون۔", "azkar.082": "(ترمذی)", "azkar.083": "۹۔ آیت الکرسی", "azkar.084": "نبی ﷺ فرمایا جیہڑا بندہ سمݨ ویلے آیت الکرسی پڑھے تاں ہک فرشتہ اوندی حفاظت کیتے مقرر کر ݙتا ویندا ہے تے صبح تئیں شیطان اوندے کول نئیں آندا۔ (بخاری) جیہڑا بستر تے لیٹ تے اینکوں پڑھسی تاں اللہ تعالیٰ اوندے آلے دوالے دے کئی گھراں دی حفاظت فرمیندا ہے۔", "azkar.085": "۱۰۔ بسم اللہ شریف <span class=\"kk-c\">۲۱ واری</span>", "azkar.086": "نبی کریم ﷺ ارشاد فرمایا جو جیہڑا بندہ سمݨ توں پہلے ۲۱ واری تسمیہ پڑھے تاں اوہ چوری، شیطانی اثرات تے اچانک موت توں محفوظ رہسی۔", "azkar.087": "۱۱۔ تسبیحِ فاطمہ", "azkar.088": "(متفق علیہ)", "azkar.089": "۱۲۔ دعائے نوم", "azkar.090": "یا اللہ! میں تیݙے ای ناں نال مردا ہاں تے تیݙے ای ناں نال جیندا ہاں۔", "azkar.091": "(متفق علیہ)", "azkar.092": "۱۳۔ سورۃ البقرہ دیاں چھیکڑی ݙو آیتاں", "azkar.093": "شبِ جمعہ تے یومِ جمعہ دے مسنون اذکار", "azkar.094": "نوٹ: ساݙے امامِ ربانی مجدد الفِ ثانیؒ کثرت نال نبی کریم ﷺ دی بارگاہ وچ قسم قسم دے درود شریف بھیڄدے ہن، خاص کر شبِ جمعہ تے یومِ جمعہ، سوموار دی رات تے سوموار دے ݙینہہ۔ آخری زمانے وچ شبِ جمعہ کوں مریدین دے نال حلقۂ ذکر توں بعد ہزار واری درود شریف بھیڄدے ہن۔", "azkar.095": "۱۔ شبِ جمعہ درود شریف <span class=\"kk-c\">ہزار واری</span>", "azkar.096": "۲۔ جمعہ توں بعد درود شریف <span class=\"kk-c\">ہزار واری</span>", "azkar.097": "شیخ عبدالقادر جیلانیؒ غنیۃ الطالبین وچ جمعہ دے ݙینہہ ایہ درود شریف پڑھݨ دی تلقین فرمائی ہے۔", "azkar.098": "۳۔ نمازِ عصر توں بعد درود شریف <span class=\"kk-c\">۸۰ واری</span>", "azkar.099": "سیدنا ابوہریرہؓ توں روایت کیتا ڳیا ارشادِ نبوی ﷺ ہے: جیں جمعہ دے ݙینہہ نمازِ عصر پڑھ تے اوں جاہ تے ٻیٹھیاں ہویاں ۸۰ واری ایہ درودِ پاک پڑھیا تاں اوندے ۸۰ سال دے ڳناہ بخش ݙتے ویسن تے اوندے نامۂ اعمال وچ ۸۰ سال دی عبادت دا ثواب لکھیا ویندا ہے۔", "azkar.100": "(دیلمی، امام سخاوی)", "azkar.101": "۴۔ کیمیائے مشائخ", "azkar.102": "شیخ عبدالحق محدث دہلویؒ اڳلے پچھلے ڳناہاں دی مغفرت کیتے ہک آزمایا ہویا وظیفہ «کیمیائے مشائخ» لکھیا ہے جو نمازِ جمعہ دا سلام پھیرݨ توں بعد تشہد دی حالت وچ سورۃ فاتحہ تے تریہے قل شریف تسمیہ سمیت ست ست واری پڑھو۔ حدیث شریف وچ ہے جو اِنہاں سورتاں دا پڑھݨ ایں جمعہ توں اڳلے جمعہ تئیں شیطان توں پناہ ݙیسی۔", "azkar.103": "(کیمیائے سعادت)", "azkar.104": "نوٹ: امامِ ربانیؒ نمازِ جمعہ توں بعد سورۃ فاتحہ تے تریہے قل تسمیہ سمیت ست ست واری پڑھدے ہن۔", "azkar.105": "<p class=\"kk-ar\" lang=\"ar\">فَاِذَا قُضِيَتِ الصَّلٰوةُ فَانْتَشِرُوْا فِي الْاَرْضِ وَابْتَغُوْا مِنْ فَضْلِ اللّٰهِ</p><p class=\"kk-ur\">وت جݙاں نماز تھی چکے تاں زمین وچ پھیل ونڄو تے اللہ دا فضل ڳولو۔ (سورۃ جمعہ: ۱۰)</p>", "azkar.106": "حضرت انسؓ فرمیندے ہن: خرید و فروخت تے دنیا کماوݨ ایں آیت دا معنیٰ کائنی، بلکہ علم دی طلب، بھراواں دی زیارت، بیماراں دی عیادت، جنازے نال ونڄݨ تے جیہڑے وی ایجھے نیک کم ہوون اوہ ایں آیت توں مراد ہن۔ کیوں جو اللہ تعالیٰ سورۃ جمعہ وچ اڳوں ارشاد فرمایا ہے:", "azkar.107": "<p class=\"kk-ar\" lang=\"ar\">وَاذْكُرُوا اللّٰهَ كَثِيْرًا لَّعَلَّكُمْ تُفْلِحُوْنَ</p><p class=\"kk-ur\">تے اللہ دا ذکر کثرت نال کرو تاں جو تساں فلاح پاؤ۔</p>", "programs.001": "سالانہ پروگرام", "atiyat.001": "عطیات", "atiyat.002": "تحریک دیاں دینی تے اصلاحی خدمتاں وچ تعاون دے خواہش مند سڄݨاں کیتے — اللہ تعالیٰ قبول فرماوے۔", "rabta.001": "رابطہ", "about.001": "ایپ بارے", "kutub.020": "خوفِ خدا تے عشقِ مصطفیٰ ﷺ", "kutub.021": "<span>مؤلف:</span> بانی تے قائد تحریک اتباعِ سنت پاکستان، پیرِ طریقت، شیرِ مجدد بدرالہدیٰ کرامت علی رزّاقی عظیمی نقشبندی <span class=\"lat\">(M.A, L.L.B)</span>", "kutub.022": "<span>معاونت:</span> انجینئر شعیب عالم عظیمی مجددی (ایم اے علومِ اسلامیہ)، <span class=\"lat\">HOD</span> الیکٹریکل ٹریڈ، گورنمنٹ ٹیکنیکل ٹریننگ انسٹی ٹیوٹ لودھراں", "kutub.023": "صفحے: <span class=\"lat\">128</span>  • اشاعت: دسمبر <span class=\"lat\">2019</span> (ڈوجھا ایڈیشن)"};
